import Chip from "@mui/material/Chip";
import Tooltip from "@mui/material/Tooltip";
import GavelIcon from "@mui/icons-material/Gavel";
import GroupsIcon from "@mui/icons-material/Groups";
import RecordVoiceOverIcon from "@mui/icons-material/RecordVoiceOver";
import LockIcon from "@mui/icons-material/Lock";
import DescriptionIcon from "@mui/icons-material/Description";

import { CASE_STATUS_LABELS, type CaseStatus } from "../../types";
import { timeUntil, isPast} from "../../utils/format";

type ChipColor = "default" | "info" | "secondary" | "success" | "primary";

/** How each phase presents itself: colour, icon, and what it means. */
const PRESENTATION: Record<CaseStatus, { color: ChipColor; icon: JSX.Element; hint: string }> = {
  filed: { color: "default", icon: <DescriptionIcon />, hint: "התביעה נקלטה." },
  witness_phase: {
    color: "info",
    icon: <RecordVoiceOverIcon />,
    hint: "הצדדים רשאים לזמן עדים.",
  },
  jury_deliberation: {
    color: "secondary",
    icon: <GroupsIcon />,
    hint: "שבעה מושבעים דנים בתיק ומצביעים.",
  },
  verdict_reached: { color: "primary", icon: <GavelIcon />, hint: "השופט נתן את פסק הדין." },
  closed: { color: "default", icon: <LockIcon />, hint: "התיק נסגר. אפשר עדיין להגיב ולסמן לייק." },
};

interface Props {
  status: CaseStatus;
  /** When the current phase ends; adds a countdown to the tooltip. */
  deadline?: string | null;
}

const CaseStatusChip = ({ status, deadline }: Props) => {
  const { color, icon, hint } = PRESENTATION[status];
  const remaining = status !== "closed" && !isPast(deadline ?? null) ? timeUntil(deadline ?? null) : "";


  return (
    <Tooltip title={remaining ? `${hint} השלב מסתיים ${remaining}.` : hint}>
      <Chip
        icon={icon}
        label={CASE_STATUS_LABELS[status]}
        color={color}
        size="small"
        variant={status === "closed" ? "outlined" : "filled"}
        data-testid="case-status-chip"
        data-status={status}
      />
    </Tooltip>
  );
}; export default CaseStatusChip;

client/src/components/case/CourtSeal.tsx:
/**
 * The court's seal, stamped on a case that has been decided.
 *
 * It appears for exactly two statuses - `verdict_reached` and `closed` - and
 * that restraint is the whole effect. A mark on every case is decoration; a
 * mark that appears only once a judge has ruled is something a reader learns to
 * scan the feed for, and it gives "still arguing" and "decided" a visible
 * difference that costs no words.
 *
 * Deliberately not a status indicator. `CaseStatusChip` is that, it sits beside
 * this, and it says which of the two states the case is in. The seal says the
 * coarser thing - the court is finished here - the way a paper court would:
 * pressed crooked, in thin ink, **over** whatever was already on the page.
 *
 * --- why it is positioned rather than laid out -----------------------------
 *
 * The first version was a flex sibling of the title, which is the tidy answer
 * and the wrong one: it reserved a column, pushed the heading aside, and looked
 * like an icon that had been given a seat. A stamp does not get a seat. It
 * lands where it lands and the text goes under it.
 *
 * So it is absolutely positioned, and two consequences follow that no caller
 * should have to think about:
 *
 *   `pointerEvents: none`  - it lies across a heading, an author link and a
 *     defendant name. Without this it would silently eat clicks on all three,
 *     and the failure would look like a broken link rather than like a seal.
 *   `mixBlendMode: multiply` and a low opacity - ink, not sticker. The text has
 *     to stay readable *through* it, because the text is the point and the seal
 *     is only the endorsement.
 *
 * No tooltip, for the same reason: a tooltip needs pointer events. The chip
 * beside it already carries the status in text, which is also why this is
 * `aria-hidden` - announcing it would read the same fact out twice.
 *
 * The parent needs `position: relative`; both call sites set it.
 */

import Box from "@mui/material/Box";

import type { CaseStatus } from "../../types";

/** The only two states a decided case can be in. */
const SEALED: readonly CaseStatus[] = ["verdict_reached", "closed"];

export const isSealed = (status: CaseStatus): boolean => SEALED.includes(status);

interface Props {
  status: CaseStatus;
  /** `card` rides on the feed card; `page` is the big one on the case page. */
  variant?: "card" | "page";
}

const CourtSeal = ({ status, variant = "card" }: Props) => {
  if (!isSealed(status)) return null;

  const page = variant === "page";

  return (
    <Box
      component="img"
      src={`${import.meta.env.BASE_URL}lolsuit-seal.svg`}
      alt=""
      aria-hidden
      data-testid="court-seal"
      data-variant={variant}
      sx={{
        position: "absolute",
        // --- placement ------------------------------------------------------
        //
        // The two variants are placed by different mechanisms on purpose.
        //
        // `card` is centred across the whole card, the way a stamp lands on a
        // document that has already been filled in. `inset: 0` plus
        // `margin: auto` is what centres it, and it is chosen over the usual
        // `top/left: 50%` + `translate(-50%, -50%)` for a specific reason: this
        // app renders RTL through stylis-plugin-rtl, which mirrors physical
        // offsets, and a mirrored `left: 50%` against an unmirrored translate
        // puts the stamp anywhere but the middle. Zero on all four sides is
        // symmetric, so there is nothing left to mirror.
        //
        // `page` is tucked into the corner beside the heading, where the space
        // actually is. `inset-inline-end` is the end of the reading direction
        // by definition - the visual left on a Hebrew page - and stays correct
        // if any of this is ever rendered LTR, which `right` would not.
        ...(page
          ? { insetInlineEnd: { xs: -8, sm: 8 }, top: { xs: -12, sm: -18 } }
          : { inset: 0, margin: "auto" }),

        // --- size -----------------------------------------------------------
        //
        // The card seal is nearly as tall as the card. That is the whole
        // gesture: a small mark in a corner reads as a badge, and there is
        // already a badge. Something pressed across the entire card reads as
        // the court having closed the file.
        width: page ? { xs: 132, sm: 190 } : { xs: 168, sm: 228 },
        height: page ? "auto" : { xs: 168, sm: 228 },

        // A stamp is never quite straight; a perfectly upright one reads as a
        // logo. Enough to be felt, not enough to look like a rendering bug.
        transform: "rotate(-8deg)",
        // The card seal lies directly across the title and the body text, so it
        // is fainter than the page one, which mostly sits in empty space. Ink
        // that hides the filing is worse than no seal.
        opacity: page ? 0.42 : 0.14,
        mixBlendMode: "multiply",
        // It lies across a heading and two links. Never eat their clicks.
        pointerEvents: "none",
        // Above the text it is stamped on, below anything a user can operate.
        zIndex: 1,
      }}
    />
  );
};

export default CourtSeal;

import { render, screen, waitFor } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { beforeEach, describe, expect, it, vi } from "vitest";

import FollowButton from "./FollowButton";
import * as api from "../../api";

/**
 * The same guarded prop-sync as LikeButton, and it is worth testing twice.
 *
 * The two components share a shape and not a line of code, so the guard is
 * implemented separately in each and can regress separately in each. The
 * comment in FollowButton points at LikeButton "for the long version", which
 * is exactly the arrangement where one of the two quietly stops matching.
 *
 * The labels get their own test for a different reason. #44 changed them from
 * "עוקב"/"עקוב", which address a man, to the pair the rest of the app uses —
 * and a button is the one control here that tells a reader what they are and
 * what to do. Queried by accessible name so reverting that is a failure rather
 * than a silent regression.
 */

vi.mock("../../api");

const follow = () => screen.getByTestId("follow-button");

beforeEach(() => {
  vi.clearAllMocks();
});

describe("FollowButton", () => {
  it("addresses a reader it has not asked in both genders", () => {
    // The unpressed label is an imperative, so it takes the imperative pair
    // rather than a second copy of the participle one.
    const { rerender } = render(<FollowButton caseId={1} following={false} count={2} />);
    expect(screen.getByRole("button", { name: /עקוב\/עקבי/ })).toBeInTheDocument();

    rerender(<FollowButton caseId={1} following count={2} />);
    expect(screen.getByRole("button", { name: /עוקב\/ת/ })).toBeInTheDocument();
  });

  it("renders the props it was given", () => {
    render(<FollowButton caseId={1} following count={2} />);

    expect(follow()).toHaveAttribute("data-following", "true");
    expect(follow()).toHaveAttribute("data-follow-count", "2");
    expect(follow()).toHaveTextContent("עוקב/ת · 2");
  });

  it("shows the word alone where the count lives elsewhere", () => {
    render(<FollowButton caseId={1} following={false} count={2} showCount={false} />);

    expect(follow()).toHaveTextContent("עקוב/עקבי");
    expect(follow()).not.toHaveTextContent("2");
  });

  it("takes the server's answer rather than incrementing its own", async () => {
    vi.mocked(api.toggleFollow).mockResolvedValue({ following: true, follow_count: 6 });
    render(<FollowButton caseId={4} following={false} count={2} />);

    await userEvent.click(follow());

    expect(api.toggleFollow).toHaveBeenCalledWith(4);
    await waitFor(() => expect(follow()).toHaveTextContent("עוקב/ת · 6"));
  });

  it("reports the server's answer to its parent", async () => {
    vi.mocked(api.toggleFollow).mockResolvedValue({ following: true, follow_count: 6 });
    const onChange = vi.fn();
    render(<FollowButton caseId={4} following={false} count={2} onChange={onChange} />);

    await userEvent.click(follow());

    await waitFor(() =>
      expect(onChange).toHaveBeenCalledWith({ following: true, follow_count: 6 }),
    );
  });

  it("adopts what the parent hands back once, and then stops", async () => {
    vi.mocked(api.toggleFollow).mockResolvedValue({ following: true, follow_count: 6 });
    const { rerender } = render(<FollowButton caseId={4} following={false} count={2} />);

    await userEvent.click(follow());
    await waitFor(() => expect(follow()).toHaveTextContent("עוקב/ת · 6"));

    rerender(<FollowButton caseId={4} following count={6} />);
    rerender(<FollowButton caseId={4} following count={6} />);

    expect(follow()).toHaveTextContent("עוקב/ת · 6");
  });

  it("keeps the server's answer when stale props arrive afterwards", async () => {
    vi.mocked(api.toggleFollow).mockResolvedValue({ following: true, follow_count: 6 });
    const { rerender } = render(<FollowButton caseId={4} following={false} count={2} />);

    await userEvent.click(follow());
    await waitFor(() => expect(follow()).toHaveTextContent("עוקב/ת · 6"));

    rerender(<FollowButton caseId={4} following={false} count={2} />);

    expect(follow()).toHaveAttribute("data-following", "true");
    expect(follow()).toHaveTextContent("עוקב/ת · 6");
  });

  it("does adopt genuinely new props", async () => {
    const { rerender } = render(<FollowButton caseId={4} following={false} count={2} />);

    rerender(<FollowButton caseId={4} following={false} count={11} />);

    expect(follow()).toHaveTextContent("עקוב/עקבי · 11");
  });

  it("leaves the previous state visible when the toggle fails", async () => {
    vi.mocked(api.toggleFollow).mockRejectedValue(new Error("התיק המבוקש לא נמצא."));
    const onChange = vi.fn();
    render(<FollowButton caseId={4} following={false} count={2} onChange={onChange} />);

    await userEvent.click(follow());

    await waitFor(() => expect(follow()).toBeEnabled());
    expect(follow()).toHaveTextContent("עקוב/עקבי · 2");
    expect(onChange).not.toHaveBeenCalled();
  });

  it("cannot be clicked twice while a request is in flight", async () => {
    let resolve!: (value: { following: boolean; follow_count: number }) => void;
    vi.mocked(api.toggleFollow).mockReturnValue(
      new Promise((res) => {
        resolve = res;
      }),
    );
    render(<FollowButton caseId={4} following={false} count={2} />);

    await userEvent.click(follow());

    expect(follow()).toBeDisabled();
    resolve({ following: true, follow_count: 3 });
    await waitFor(() => expect(follow()).toBeEnabled());
    expect(api.toggleFollow).toHaveBeenCalledTimes(1);
  });

  it("is inert when the parent disables it", async () => {
    render(<FollowButton caseId={4} following={false} count={2} disabled />);

    expect(follow()).toBeDisabled();
    await userEvent.click(follow(), { pointerEventsCheck: 0 });
    expect(api.toggleFollow).not.toHaveBeenCalled();
  });
});

import { useEffect, useRef, useState } from "react";
import Button from "@mui/material/Button";
import BookmarkIcon from "@mui/icons-material/Bookmark";
import BookmarkBorderIcon from "@mui/icons-material/BookmarkBorder";

import * as api from "../../api";

interface Props {
  caseId: number;
  following: boolean;
  count: number;
  disabled?: boolean;
  /** The feed card carries the number in its stat row, so the button there is
   *  the word alone and the count is not printed twice. */
  showCount?: boolean;
  /** Told the server's answer, so a parent showing the same numbers elsewhere
   *  - the feed card's stat row - can redraw them without a refetch. */
  onChange?: (next: { following: boolean; follow_count: number }) => void;
}

const FollowButton = ({
  caseId,
  following,
  count,
  disabled,
  showCount = true,
  onChange,
}: Props) => {
  const [state, setState] = useState({ following, follow_count: count });
  const [busy, setBusy] = useState(false);

  // Same guarded prop-sync as LikeButton, for the same reason: the case page
  // refetches every ten seconds while a trial is live, and a naive effect
  // would overwrite the server's fresh answer with props the parent has not
  // refetched yet. Comparing against the last props we saw is what makes it
  // safe. See LikeButton.tsx for the long version.
  const lastProps = useRef({ following, count });
  useEffect(() => {
    if (lastProps.current.following === following && lastProps.current.count === count) return;
    lastProps.current = { following, count };
    setState({ following, follow_count: count });
  }, [following, count]);

  const toggle = async () => {
    setBusy(true);
    try {
      // The server returns the authoritative state AND the new total, so the
      // count cannot drift by being incremented from a stale one.
      const next = await api.toggleFollow(caseId);
      setState(next);
      // Safe to tell the parent, which will hand these straight back as props:
      // the sync below compares against the last props it SAW, so it adopts
      // them once and stops. See LikeButton for why that guard is written that
      // way rather than around a `busy` flag.
      onChange?.(next);
    } catch {
      // Leaving the previous state visible is the honest outcome of a failed
      // toggle; an optimistic flip here would claim something untrue.
    } finally {
      setBusy(false);
    }
  };

  return (
    <Button
      onClick={toggle}
      disabled={disabled || busy}
      color={state.following ? "primary" : "inherit"}
      startIcon={state.following ? <BookmarkIcon /> : <BookmarkBorderIcon />}
      data-testid="follow-button"
      data-following={state.following}
      data-follow-count={state.follow_count}
    >
      {/* Both genders, the way the rest of the app addresses a reader it has
          not asked - "עוקב/ת" is already what the profile and the followed-
          cases dialog say. The unpressed label is the imperative, so it takes
          the imperative pair rather than the same one. */}
      {state.following ? "עוקב/ת" : "עקוב/עקבי"}
      {showCount && ` · ${state.follow_count}`}
    </Button>
  );
}; export default FollowButton;

