import { render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import InfiniteScroll from "./InfiniteScroll";

/**
 * The scroll sentinel.
 *
 * jsdom has no IntersectionObserver and no layout, so a real one would never
 * fire here. The stub below records what was observed and hands the test a
 * trigger, which is the part worth pinning: WHEN the component asks for the
 * next page, and — more importantly — when it does not.
 */

interface Instance {
  callback: IntersectionObserverCallback;
  observed: Element[];
  disconnected: boolean;
}

let instances: Instance[] = [];

class FakeObserver {
  private instance: Instance;

  constructor(callback: IntersectionObserverCallback) {
    this.instance = { callback, observed: [], disconnected: false };
    instances.push(this.instance);
  }

  observe(node: Element) {
    this.instance.observed.push(node);
  }

  disconnect() {
    this.instance.disconnected = true;
  }

  unobserve() {}
  takeRecords() {
    return [];
  }
}

/** Pretend the sentinel scrolled into view. */
const scrollIntoView = (isIntersecting = true) => {
  for (const instance of instances) {
    instance.callback(
      [{ isIntersecting } as IntersectionObserverEntry],
      {} as IntersectionObserver,
    );
  }
};

beforeEach(() => {
  instances = [];
  vi.stubGlobal("IntersectionObserver", FakeObserver);
});

afterEach(() => {
  vi.unstubAllGlobals();
});

describe("InfiniteScroll", () => {
  it("asks for the next page when the sentinel comes into view", () => {
    const onLoadMore = vi.fn();
    render(<InfiniteScroll hasMore loading={false} onLoadMore={onLoadMore} />);

    expect(instances[0].observed).toHaveLength(1);
    scrollIntoView();

    expect(onLoadMore).toHaveBeenCalledTimes(1);
  });

  it("ignores the sentinel while it is out of view", () => {
    const onLoadMore = vi.fn();
    render(<InfiniteScroll hasMore loading={false} onLoadMore={onLoadMore} />);

    scrollIntoView(false);

    expect(onLoadMore).not.toHaveBeenCalled();
  });

  it("does not stack a second request on top of one already in flight", () => {
    const onLoadMore = vi.fn();
    render(<InfiniteScroll hasMore loading onLoadMore={onLoadMore} />);

    scrollIntoView();

    expect(instances).toHaveLength(0);
    expect(onLoadMore).not.toHaveBeenCalled();
  });

  it("renders nothing at the end of the list", () => {
    const { container } = render(
      <InfiniteScroll hasMore={false} loading={false} onLoadMore={vi.fn()} />,
    );

    expect(container).toBeEmptyDOMElement();
  });

  it("keeps the button as the manual route to the same page", async () => {
    const onLoadMore = vi.fn();
    render(<InfiniteScroll hasMore loading={false} onLoadMore={onLoadMore} label="טען עוד" />);

    await userEvent.click(screen.getByRole("button", { name: "טען עוד" }));

    expect(onLoadMore).toHaveBeenCalledTimes(1);
  });

  it("stops observing once it is unmounted", () => {
    const { unmount } = render(
      <InfiniteScroll hasMore loading={false} onLoadMore={vi.fn()} />,
    );

    unmount();

    expect(instances[0].disconnected).toBe(true);
  });

  it("works where the browser has no IntersectionObserver at all", async () => {
    vi.stubGlobal("IntersectionObserver", undefined);
    const onLoadMore = vi.fn();

    render(<InfiniteScroll hasMore loading={false} onLoadMore={onLoadMore} label="טען עוד" />);
    await userEvent.click(screen.getByRole("button", { name: "טען עוד" }));

    expect(onLoadMore).toHaveBeenCalledTimes(1);
  });
});

import { useEffect, useRef } from "react";
import Box from "@mui/material/Box";
import Button from "@mui/material/Button";

interface Props {
  /** Whether there is another page to fetch. */
  hasMore: boolean;
  /** True while a page is in flight; suppresses a second request. */
  loading: boolean;
  onLoadMore: () => void;
  /** The button's resting label. The busy label is shared. */
  label?: string;
  testId?: string;
}

/**
 * "More posts load as the user scrolls down."
 *
 * An empty div is parked below the last row and watched with an
 * IntersectionObserver; when it comes into view the next page is requested.
 * The observer watches a SENTINEL rather than the scroll position because it
 * costs nothing while the user is elsewhere on the page — no scroll handler
 * firing on every frame, no reading layout to compare offsets — and it works
 * the same whether the list scrolls in the window or inside a dialog.
 *
 * `rootMargin` starts the fetch a screen early, so the page below usually
 * arrives before the reader reaches the bottom.
 *
 * The button stays. It is not a leftover: it is the keyboard and screen-reader
 * path to the next page, the fallback where IntersectionObserver is missing,
 * and the only way to advance the list in an automated browser, where the
 * headless tab reports itself hidden and the observer therefore never fires.
 * Both routes call the same `onLoadMore`.
 */
const InfiniteScroll = ({ hasMore, loading, onLoadMore, label = "טען עוד", testId }: Props) => {
  const sentinel = useRef<HTMLDivElement | null>(null);

  // `onLoadMore` is rebuilt on every render of the parent (it closes over the
  // current item count). Keeping it in a ref lets the observer be created once
  // per hasMore/loading change instead of once per render.
  const loadMore = useRef(onLoadMore);
  loadMore.current = onLoadMore;

  useEffect(() => {
    const node = sentinel.current;
    if (!node || !hasMore || loading) return;
    if (typeof IntersectionObserver === "undefined") return;

    const observer = new IntersectionObserver(
      (entries) => {
        if (entries.some((entry) => entry.isIntersecting)) loadMore.current();
      },
      { rootMargin: "600px 0px" },
    );
    observer.observe(node);
    return () => observer.disconnect();
  }, [hasMore, loading]);

  if (!hasMore) return null;

  return (
    <Box sx={{ textAlign: "center", mt: 2 }} data-testid={testId}>
      <div ref={sentinel} aria-hidden data-testid="infinite-scroll-sentinel" />
      <Button onClick={onLoadMore} disabled={loading}>
        {loading ? "טוען…" : label}
      </Button>
    </Box>
  );
}; export default InfiniteScroll;

import Alert from "@mui/material/Alert";
import Box from "@mui/material/Box";
import CircularProgress from "@mui/material/CircularProgress";
import Typography from "@mui/material/Typography";
import type { ReactNode } from "react";

/** The three states every data-loading view needs, so no page reinvents them. */

export const Loading = ({ label = "טוען…" }: { label?: string }) => {
  return (
    <Box sx={{ display: "flex", justifyContent: "center", alignItems: "center", gap: 2, py: 6 }}>
      <CircularProgress size={28} />
      <Typography color="text.secondary">{label}</Typography>
    </Box>
  );
};

export const ErrorNote = ({ message }: { message: string }) => {
  return (
    <Alert severity="error" sx={{ my: 2 }} data-testid="error-note">
      {message}
    </Alert>
  );
};

export const EmptyState = ({
  title,
  description,
  action,
}: {
  title: string;
  description?: string;
  action?: ReactNode;
}) => {
  return (
    <Box sx={{ textAlign: "center", py: 6, px: 2 }} data-testid="empty-state">
      <Typography variant="h6" gutterBottom>
        {title}
      </Typography>
      {description && (
        <Typography color="text.secondary" sx={{ mb: 2 }}>
          {description}
        </Typography>
      )}
      {action}
    </Box>
  );
};

