interface Props {
  caseId: number;
  onTestified: () => void;
}

/**
 * Shown only when the server says `viewer.can_testify` — i.e. you were
 * summoned, have not answered, and the witness phase is still open. The client
 * never works that out for itself.
 */
const TestifyForm = ({ caseId, onTestified }: Props) => {
  const [body, setBody] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  const submit = async (event: React.FormEvent) => {
    event.preventDefault();
    if (!body.trim()) return;
    setError(null);
    setBusy(true);
    try {
      await api.testify(caseId, body.trim());
      setBody("");
      onTestified();
    } catch (err) {
      setError(err instanceof Error ? err.message : "לא הצלחנו למסור את העדות.");
    } finally {
      setBusy(false);
    }
  };

  return (
    <Paper
      sx={{ p: { xs: 2, sm: 3 }, borderInlineStart: "4px solid", borderColor: "info.main" }}
      component="form"
      onSubmit={submit}
      data-testid="testify-form"
    >
      <Typography variant="h6" gutterBottom>
        זומנת למסור עדות
      </Typography>
      <Alert severity="info" sx={{ mb: 2 }}>
        העדות תיווסף לפרוטוקול הדיון ותוצג לחבר המושבעים. אפשר למסור עדות אחת בלבד.
      </Alert>

      {error && <ErrorNote message={error} />}

      <TextField
        value={body}
        onChange={(e) => setBody(e.target.value)}
        placeholder="ספר/י לבית המשפט מה ראית…"
        multiline
        minRows={3}
        fullWidth
        inputProps={{ "data-testid": "testify-body", maxLength: 4000 }}
        sx={{ fontFamily: DOC_FONT }}
      />

      <Box sx={{ display: "flex", justifyContent: "flex-end", mt: 1.5 }}>
        <Button
          type="submit"
          variant="contained"
          disabled={busy || !body.trim()}
          data-testid="testify-submit"
        >
          {busy ? "מוסר…" : "מסור עדות"}
        </Button>
      </Box>
    </Paper>
  );
}; export default TestifyForm;

import Avatar from "@mui/material/Avatar";
import Box from "@mui/material/Box";
import Chip from "@mui/material/Chip";
import Paper from "@mui/material/Paper";
import Stack from "@mui/material/Stack";
import Typography from "@mui/material/Typography";

import { SUMMONS_STATUS_LABELS, type Summons, type SummonsStatus } from "../../types";
import { initials } from "../../utils/format";

const STATUS_COLOR: Record<SummonsStatus, "default" | "success" | "error"> = {
  pending: "default",
  testified: "success",
  no_show: "error",
};

const SIDE_LABEL = { plaintiff: "עדי התביעה", defense: "עדי ההגנה" } as const;

const WitnessList = ({ summons }: { summons: Summons[] }) => {
  if (summons.length === 0) return null;

  const sides = (["plaintiff", "defense"] as const).filter((side) =>
    summons.some((s) => s.side === side),
  );

  return (
    <Paper sx={{ p: { xs: 2, sm: 3 } }} data-testid="witness-list">
      <Typography variant="h6" gutterBottom>
        רשימת העדים
      </Typography>

      <Stack spacing={2}>
        {sides.map((side) => (
          <Box key={side}>
            <Typography variant="subtitle2" color="text.secondary" gutterBottom>
              {SIDE_LABEL[side]}
            </Typography>
            <Stack spacing={1}>
              {summons
                .filter((s) => s.side === side)
                .map((s) => (
                  <Stack
                    key={s.id}
                    direction="row"
                    spacing={1.5}
                    alignItems="center"
                    data-testid="witness-row"
                    data-status={s.status}
                  >
                    <Avatar src={s.witness.avatar_url ?? undefined} sx={{ width: 30, height: 30 }}>
                      {initials(s.witness.name)}
                    </Avatar>
                    <Typography variant="body2" sx={{ flex: 1, minWidth: 0 }} noWrap>
                      {s.witness.name}
                    </Typography>
                    <Chip
                      size="small"
                      variant="outlined"
                      color={STATUS_COLOR[s.status]}
                      label={SUMMONS_STATUS_LABELS[s.status]}
                    />
                  </Stack>
                ))}
            </Stack>
          </Box>
        ))}
      </Stack>
    </Paper>
  );
}; export default WitnessList;

