import { act, renderHook, waitFor } from "@testing-library/react";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import { useNotificationStream } from "./useNotificationStream";
import type { Notification } from "../types";

/**
 * SSE where it works, polling where it does not.
 *
 * jsdom has no EventSource, so the stub below is both the fake and the
 * mechanism: it records every stream that was opened and hands the test the
 * two triggers that matter — deliver a frame, and fail.
 *
 * The behaviour worth pinning is the fallback, and specifically that it is
 * ONE-WAY. Falling back is permanent for the session rather than retried
 * forever: if a proxy is buffering event streams, reconnecting will not fix
 * it, and a reconnect loop is worse than polling. So the tests below check
 * both halves — that a single failure reconnects, and that two inside the
 * window stop trying for good.
 */

interface Stream {
  url: string;
  listeners: Record<string, (event: MessageEvent) => void>;
  onerror: (() => void) | null;
  closed: boolean;
}

let streams: Stream[] = [];

/**
 * The fetch stub, kept as a handle rather than read back off the global.
 *
 * `globalThis.fetch` is typed as the real thing, so asserting on it would need
 * a cast at every call site - and `global` is not in tsconfig's `types` list
 * at all, so `npm run lint` rejects it outright.
 */
let polls: ReturnType<typeof vi.fn>;

const stubFetch = (
  impl: () => Promise<unknown> = async () => ({ ok: true, json: async () => ({ notifications: [] }) }),
) => {
  polls = vi.fn(impl);
  vi.stubGlobal("fetch", polls);
};

class FakeEventSource {
  private stream: Stream;

  constructor(url: string) {
    this.stream = { url, listeners: {}, onerror: null, closed: false };
    streams.push(this.stream);
  }

  addEventListener(name: string, handler: (event: MessageEvent) => void) {
    this.stream.listeners[name] = handler;
  }

  set onerror(handler: () => void) {
    this.stream.onerror = handler;
  }

  close() {
    this.stream.closed = true;
  }
}

/** Push one notification down the newest open stream. */
const deliver = (notification: Partial<Notification> & { id: number }) => {
  const stream = streams[streams.length - 1];
  stream.listeners.notification?.({
    data: JSON.stringify(notification),
  } as MessageEvent);
};

/** Break the newest stream, the way a proxy closing the connection would. */
const breakStream = () => streams[streams.length - 1].onerror?.();

const notification = (id: number): Notification =>
  ({ id, type: "like", payload: {}, is_read: false }) as unknown as Notification;

beforeEach(() => {
  streams = [];
  vi.stubGlobal("EventSource", FakeEventSource);
  stubFetch();
});

afterEach(() => {
  vi.unstubAllGlobals();
  vi.useRealTimers();
});

describe("useNotificationStream", () => {
  it("opens nothing at all while it is disabled", () => {
    // NotificationContext gates on a `loaded` flag, because at since=0 the
    // server replays the user's entire history and every row arrives new.
    renderHook(() =>
      useNotificationStream({ enabled: false, since: 0, onNotification: vi.fn() }),
    );

    expect(streams).toHaveLength(0);
  });

  it("opens a stream from the cursor it was given", () => {
    renderHook(() =>
      useNotificationStream({ enabled: true, since: 42, onNotification: vi.fn() }),
    );

    expect(streams).toHaveLength(1);
    expect(streams[0].url).toContain("since=42");
  });

  it("hands every frame to the callback", () => {
    const onNotification = vi.fn();
    renderHook(() => useNotificationStream({ enabled: true, since: 0, onNotification }));

    act(() => deliver(notification(1)));
    act(() => deliver(notification(2)));

    expect(onNotification).toHaveBeenCalledTimes(2);
    expect(onNotification.mock.calls[1][0].id).toBe(2);
  });

  it("ignores a frame it cannot parse rather than tearing down the stream", () => {
    const onNotification = vi.fn();
    renderHook(() => useNotificationStream({ enabled: true, since: 0, onNotification }));

    act(() => {
      streams[0].listeners.notification?.({ data: "not json" } as MessageEvent);
    });

    expect(onNotification).not.toHaveBeenCalled();
    expect(streams[0].closed).toBe(false);

    act(() => deliver(notification(1)));
    expect(onNotification).toHaveBeenCalledTimes(1);
  });

  it("reconnects once, because the server caps every stream's lifetime", () => {
    // A clean close is the NORMAL case here, not an error — so one failure
    // must not be enough to conclude that SSE is broken.
    vi.useFakeTimers();
    renderHook(() =>
      useNotificationStream({ enabled: true, since: 0, onNotification: vi.fn() }),
    );

    act(() => breakStream());
    act(() => void vi.advanceTimersByTime(1000));

    expect(streams).toHaveLength(2);
    expect(polls).not.toHaveBeenCalled();
  });

  it("resumes a reconnect from the last id it actually saw", () => {
    vi.useFakeTimers();
    renderHook(() =>
      useNotificationStream({ enabled: true, since: 0, onNotification: vi.fn() }),
    );

    act(() => deliver(notification(7)));
    act(() => breakStream());
    act(() => void vi.advanceTimersByTime(1000));

    expect(streams[1].url).toContain("since=7");
  });

  it("gives up on SSE for good after two failures inside the window", async () => {
    vi.useFakeTimers();
    renderHook(() =>
      useNotificationStream({ enabled: true, since: 0, onNotification: vi.fn() }),
    );

    act(() => breakStream());
    act(() => void vi.advanceTimersByTime(1000));
    act(() => breakStream());

    // Polling started, and no third stream was opened.
    expect(polls).toHaveBeenCalledTimes(1);
    expect(streams).toHaveLength(2);

    act(() => void vi.advanceTimersByTime(5000));
    expect(streams).toHaveLength(2);
  });

  it("keeps polling on its own interval once it has fallen back", () => {
    vi.useFakeTimers();
    renderHook(() =>
      useNotificationStream({ enabled: true, since: 0, onNotification: vi.fn() }),
    );

    act(() => breakStream());
    act(() => void vi.advanceTimersByTime(1000));
    act(() => breakStream());

    act(() => void vi.advanceTimersByTime(10_000));
    act(() => void vi.advanceTimersByTime(10_000));

    expect(polls).toHaveBeenCalledTimes(3);
  });

  it("polls straight away where the browser has no EventSource at all", () => {
    vi.stubGlobal("EventSource", undefined);

    renderHook(() =>
      useNotificationStream({ enabled: true, since: 5, onNotification: vi.fn() }),
    );

    expect(polls).toHaveBeenCalledTimes(1);
    expect(polls.mock.calls[0][0]).toContain("since=5");
  });

  it("polling advances the same cursor and calls the same callback", async () => {
    vi.stubGlobal("EventSource", undefined);
    stubFetch(async () => ({
      ok: true,
      json: async () => ({ notifications: [notification(11), notification(12)] }),
    }));
    const onNotification = vi.fn();

    renderHook(() => useNotificationStream({ enabled: true, since: 0, onNotification }));

    // Both transports are interchangeable to every consumer, which is exactly
    // why the polling path could ship first and SSE be layered on after.
    await waitFor(() => expect(onNotification).toHaveBeenCalledTimes(2));
    expect(onNotification.mock.calls[1][0].id).toBe(12);
  });

  it("sends the session cookie when it polls", async () => {
    vi.stubGlobal("EventSource", undefined);

    renderHook(() =>
      useNotificationStream({ enabled: true, since: 0, onNotification: vi.fn() }),
    );

    await waitFor(() => expect(polls).toHaveBeenCalled());
    const [, options] = polls.mock.calls[0];
    expect(options.credentials).toBe("include");
  });

  it("a failed poll is swallowed rather than surfaced", async () => {
    vi.stubGlobal("EventSource", undefined);
    stubFetch(async () => {
      throw new Error("offline");
    });
    const onNotification = vi.fn();

    renderHook(() => useNotificationStream({ enabled: true, since: 0, onNotification }));

    await waitFor(() => expect(polls).toHaveBeenCalled());
    expect(onNotification).not.toHaveBeenCalled();
  });

  it("a non-ok poll delivers nothing", async () => {
    vi.stubGlobal("EventSource", undefined);
    stubFetch(async () => ({ ok: false, json: async () => ({}) }));
    const onNotification = vi.fn();

    renderHook(() => useNotificationStream({ enabled: true, since: 0, onNotification }));

    await waitFor(() => expect(polls).toHaveBeenCalled());
    expect(onNotification).not.toHaveBeenCalled();
  });

  it("the cursor only ever moves forwards", () => {
    const onNotification = vi.fn();
    const { rerender } = renderHook(
      ({ since }: { since: number }) =>
        useNotificationStream({ enabled: true, since, onNotification }),
      { initialProps: { since: 10 } },
    );

    // A parent recomputing a lower `since` must not rewind the stream and
    // replay what the user has already been shown.
    rerender({ since: 3 });
    vi.useFakeTimers();
    act(() => breakStream());
    act(() => void vi.advanceTimersByTime(1000));

    expect(streams[1].url).toContain("since=10");
  });

  it("closes the stream and clears the timer when it goes away", () => {
    vi.useFakeTimers();
    const { unmount } = renderHook(() =>
      useNotificationStream({ enabled: true, since: 0, onNotification: vi.fn() }),
    );

    unmount();

    expect(streams[0].closed).toBe(true);
    // And nothing reconnects afterwards.
    act(() => void vi.advanceTimersByTime(5000));
    expect(streams).toHaveLength(1);
  });

  it("a stream that breaks after unmount does not reopen", () => {
    vi.useFakeTimers();
    const { unmount } = renderHook(() =>
      useNotificationStream({ enabled: true, since: 0, onNotification: vi.fn() }),
    );
    const stream = streams[0];

    unmount();
    act(() => stream.onerror?.());
    act(() => void vi.advanceTimersByTime(5000));

    expect(streams).toHaveLength(1);
    expect(polls).not.toHaveBeenCalled();
  });

  it("always calls the newest callback, not the one it opened with", () => {
    const first = vi.fn();
    const second = vi.fn();
    const { rerender } = renderHook(
      ({ onNotification }: { onNotification: (n: Notification) => void }) =>
        useNotificationStream({ enabled: true, since: 0, onNotification }),
      { initialProps: { onNotification: first } },
    );

    rerender({ onNotification: second });
    act(() => deliver(notification(1)));

    // Held in a ref, so reconnecting does not depend on render timing — and a
    // re-render does not tear the stream down either.
    expect(first).not.toHaveBeenCalled();
    expect(second).toHaveBeenCalledTimes(1);
    expect(streams).toHaveLength(1);
  });
});

import { useEffect, useRef } from "react";

import type { Notification } from "../types";

const POLL_INTERVAL_MS = 10_000;
/** Two failures inside this window means SSE is not working here. */
const FAILURE_WINDOW_MS = 30_000;
const FAILURE_LIMIT = 2;

interface Options {
  enabled: boolean;
  /** Where to resume from. Both transports use the same cursor. */
  since: number;
  onNotification: (notification: Notification) => void;
}

/**
 * Live notifications, over SSE where it works and polling where it does not.
 *
 * Both transports call the identical `onNotification` callback and advance the
 * same `notifications.id` cursor, so every consumer is transport-agnostic —
 * which is exactly why the polling path could ship first and SSE could be
 * layered on afterwards without touching the bell.
 *
 * Falling back is permanent for the session rather than retried forever: if a
 * proxy is buffering event streams, reconnecting will not fix it, and a
 * reconnect loop is worse than polling.
 */
export const useNotificationStream = ({ enabled, since, onNotification }: Options) => {
  // Held in refs so reconnecting does not depend on render timing.
  const cursor = useRef(since);
  const handler = useRef(onNotification);
  handler.current = onNotification;

  useEffect(() => {
    cursor.current = Math.max(cursor.current, since);
  }, [since]);

  useEffect(() => {
    if (!enabled) return;

    let stopped = false;
    let source: EventSource | null = null;
    let pollTimer: ReturnType<typeof setInterval> | null = null;
    let failures: number[] = [];

    const poll = async () => {
      try {
        const response = await fetch(`/api/notifications?since=${cursor.current}`, {
          credentials: "include",
        });
        if (!response.ok) return;
        const body = (await response.json()) as { notifications: Notification[] };
        for (const notification of body.notifications) {
          cursor.current = Math.max(cursor.current, notification.id);
          handler.current(notification);
        }
      } catch {
        // A failed poll is not worth surfacing; the next one may succeed.
      }
    };

    const startPolling = () => {
      if (pollTimer || stopped) return;
      void poll();
      pollTimer = setInterval(() => void poll(), POLL_INTERVAL_MS);
    };

    const connect = () => {
      if (stopped) return;
      if (typeof EventSource === "undefined") {
        startPolling();
        return;
      }

      source = new EventSource(`/api/notifications/stream?since=${cursor.current}`);

      source.addEventListener("notification", (event) => {
        try {
          const notification = JSON.parse((event as MessageEvent).data) as Notification;
          cursor.current = Math.max(cursor.current, notification.id);
          handler.current(notification);
        } catch {
          // Ignore a frame we cannot parse rather than tearing down the stream.
        }
      });

      source.onerror = () => {
        source?.close();
        source = null;
        if (stopped) return;

        const now = Date.now();
        failures = [...failures, now].filter((at) => now - at < FAILURE_WINDOW_MS);

        if (failures.length >= FAILURE_LIMIT) {
          // SSE is not viable here. Polling from now on.
          startPolling();
        } else {
          // The server caps each stream's lifetime, so a clean close is the
          // normal case rather than an error — reconnect promptly.
          setTimeout(connect, 1000);
        }
      };
    }; 

    connect();

    return () => {
      stopped = true;
      source?.close();
      if (pollTimer) clearInterval(pollTimer);
    };
  }, [enabled]);
};

client/src/hooks/usePagedList.test.ts:
import { act, renderHook, waitFor } from "@testing-library/react";
import { describe, expect, it, vi } from "vitest";

import { usePagedList } from "./usePagedList";

/**
 * The accumulating list.
 *
 * Every test here drives a `fetchPage` the test itself controls, because the
 * three things worth pinning are all about WHEN the hook calls it and what it
 * does with an answer that arrives late:
 *
 *   - the offset comes from what has accumulated, not from a page counter;
 *   - a response whose token is stale is dropped rather than appended;
 *   - an empty later page ends the list whatever `total` claims.
 *
 * `deferred()` hands back a promise plus its resolver, which is what lets a
 * test resolve page one AFTER a dependency change - the ordering the token
 * exists for and the only way to reproduce it deterministically.
 */

interface Row {
  id: number;
}

const page = (ids: number[], total: number) => ({
  items: ids.map((id) => ({ id })),
  total,
});

/** A promise the test resolves by hand, so response order is a choice. */
const deferred = <T,>() => {
  let resolve!: (value: T) => void;
  let reject!: (reason?: unknown) => void;
  const promise = new Promise<T>((res, rej) => {
    resolve = res;
    reject = rej;
  });
  return { promise, resolve, reject };
};

describe("usePagedList", () => {
  it("loads the first page on mount", async () => {
    const fetchPage = vi.fn().mockResolvedValue(page([1, 2], 5));

    const { result } = renderHook(() => usePagedList<Row>(fetchPage, [], 2));

    await waitFor(() => expect(result.current.loading).toBe(false));
    expect(fetchPage).toHaveBeenCalledWith(0, 2);
    expect(result.current.items).toHaveLength(2);
    expect(result.current.total).toBe(5);
    expect(result.current.hasMore).toBe(true);
  });

  it("asks for the next page at the offset it has already accumulated", async () => {
    const fetchPage = vi
      .fn()
      .mockResolvedValueOnce(page([1, 2], 5))
      .mockResolvedValueOnce(page([3, 4], 5));

    const { result } = renderHook(() => usePagedList<Row>(fetchPage, [], 2));
    await waitFor(() => expect(result.current.loading).toBe(false));

    act(() => result.current.loadMore());
    await waitFor(() => expect(result.current.loading).toBe(false));

    // Not "page 2" — the offset is items.length, so it stays correct even if
    // a page came back short.
    expect(fetchPage).toHaveBeenLastCalledWith(2, 2);
  });

  it("appends the next page instead of replacing what is on screen", async () => {
    const fetchPage = vi
      .fn()
      .mockResolvedValueOnce(page([1, 2], 4))
      .mockResolvedValueOnce(page([3, 4], 4));

    const { result } = renderHook(() => usePagedList<Row>(fetchPage, [], 2));
    await waitFor(() => expect(result.current.loading).toBe(false));

    act(() => result.current.loadMore());
    await waitFor(() => expect(result.current.items).toHaveLength(4));

    expect(result.current.items.map((row) => row.id)).toEqual([1, 2, 3, 4]);
    expect(result.current.hasMore).toBe(false);
  });

  it("does not stack a second page request on top of one already in flight", async () => {
    const first = deferred<{ items: Row[]; total: number }>();
    const fetchPage = vi.fn().mockReturnValue(first.promise);

    const { result } = renderHook(() => usePagedList<Row>(fetchPage, [], 2));

    act(() => result.current.loadMore());

    expect(fetchPage).toHaveBeenCalledTimes(1);

    await act(async () => {
      first.resolve(page([1, 2], 4));
    });
  });

  it("drops a response whose query is no longer the current one", async () => {
    // The regression the token exists for: type quickly in a search box and a
    // slow early response appends itself underneath a later one.
    const slow = deferred<{ items: Row[]; total: number }>();
    const fast = deferred<{ items: Row[]; total: number }>();
    const fetchPage = vi
      .fn()
      .mockReturnValueOnce(slow.promise)
      .mockReturnValueOnce(fast.promise);

    const { result, rerender } = renderHook(
      ({ term }: { term: string }) => usePagedList<Row>(fetchPage, [term], 2),
      { initialProps: { term: "a" } },
    );

    rerender({ term: "ab" });

    await act(async () => {
      fast.resolve(page([9], 1));
    });
    // Page one of the ABANDONED query, arriving last.
    await act(async () => {
      slow.resolve(page([1, 2], 2));
    });

    expect(result.current.items.map((row) => row.id)).toEqual([9]);
    expect(result.current.total).toBe(1);
  });

  it("drops a stale failure too, so an abandoned query cannot show its error", async () => {
    const slow = deferred<{ items: Row[]; total: number }>();
    const fast = deferred<{ items: Row[]; total: number }>();
    const fetchPage = vi
      .fn()
      .mockReturnValueOnce(slow.promise)
      .mockReturnValueOnce(fast.promise);

    const { result, rerender } = renderHook(
      ({ term }: { term: string }) => usePagedList<Row>(fetchPage, [term], 2),
      { initialProps: { term: "a" } },
    );

    rerender({ term: "ab" });

    await act(async () => {
      fast.resolve(page([9], 1));
    });
    await act(async () => {
      slow.reject(new Error("הבקשה הקודמת נכשלה"));
    });

    expect(result.current.error).toBeNull();
    expect(result.current.items).toHaveLength(1);
  });

  it("starts again from the top when the query changes", async () => {
    const fetchPage = vi
      .fn()
      .mockResolvedValueOnce(page([1, 2], 4))
      .mockResolvedValueOnce(page([7], 1));

    const { result, rerender } = renderHook(
      ({ term }: { term: string }) => usePagedList<Row>(fetchPage, [term], 2),
      { initialProps: { term: "a" } },
    );
    await waitFor(() => expect(result.current.items).toHaveLength(2));

    rerender({ term: "b" });
    await waitFor(() => expect(result.current.items).toHaveLength(1));

    // Page three of one query has nothing to do with page three of another.
    expect(fetchPage).toHaveBeenLastCalledWith(0, 2);
    expect(result.current.items.map((row) => row.id)).toEqual([7]);
  });

  it("ends the list on an empty later page whatever the total claims", async () => {
    // `total` and the rows can disagree honestly — something was withdrawn or
    // hidden between the two requests. Believing `total` leaves hasMore true
    // forever, which with the scroll sentinel is a request loop.
    const fetchPage = vi
      .fn()
      .mockResolvedValueOnce(page([1, 2], 10))
      .mockResolvedValueOnce(page([], 10));

    const { result } = renderHook(() => usePagedList<Row>(fetchPage, [], 2));
    await waitFor(() => expect(result.current.loading).toBe(false));

    act(() => result.current.loadMore());
    await waitFor(() => expect(result.current.hasMore).toBe(false));

    expect(result.current.total).toBe(2);
    expect(result.current.items).toHaveLength(2);
  });

  it("still believes a total larger than the first page", async () => {
    // The correction above must not fire on page one, or a list longer than
    // one page could never be paged at all.
    const fetchPage = vi.fn().mockResolvedValue(page([], 10));

    const { result } = renderHook(() => usePagedList<Row>(fetchPage, [], 2));
    await waitFor(() => expect(result.current.loading).toBe(false));

    expect(result.current.total).toBe(10);
  });

  it("surfaces the server's own message when a page fails", async () => {
    const fetchPage = vi.fn().mockRejectedValue(new Error("התיק המבוקש לא נמצא."));

    const { result } = renderHook(() => usePagedList<Row>(fetchPage, [], 2));

    await waitFor(() => expect(result.current.error).toBe("התיק המבוקש לא נמצא."));
    expect(result.current.loading).toBe(false);
  });

  it("falls back to a Hebrew message when the failure is not an Error", async () => {
    const fetchPage = vi.fn().mockRejectedValue("something odd");

    const { result } = renderHook(() => usePagedList<Row>(fetchPage, [], 2));

    await waitFor(() => expect(result.current.error).toBe("אירעה שגיאה."));
  });

  it("reload discards what was accumulated and fetches from zero", async () => {
    const fetchPage = vi
      .fn()
      .mockResolvedValueOnce(page([1, 2], 4))
      .mockResolvedValueOnce(page([3, 4], 4))
      .mockResolvedValueOnce(page([5, 6], 4));

    const { result } = renderHook(() => usePagedList<Row>(fetchPage, [], 2));
    await waitFor(() => expect(result.current.loading).toBe(false));
    act(() => result.current.loadMore());
    await waitFor(() => expect(result.current.items).toHaveLength(4));

    act(() => result.current.reload());
    await waitFor(() => expect(result.current.items).toHaveLength(2));

    expect(fetchPage).toHaveBeenLastCalledWith(0, 2);
    expect(result.current.items.map((row) => row.id)).toEqual([5, 6]);
  });

  it("rewrites a row in place without disturbing the pages around it", async () => {
    // patchItems exists so liking from the feed redraws one number. reload()
    // would also be truthful and would throw away every page loaded so far,
    // scrolling the reader back to the top to change a single digit.
    const fetchPage = vi
      .fn()
      .mockResolvedValueOnce(page([1, 2], 4))
      .mockResolvedValueOnce(page([3, 4], 4));

    const { result } = renderHook(() => usePagedList<Row>(fetchPage, [], 2));
    await waitFor(() => expect(result.current.loading).toBe(false));
    act(() => result.current.loadMore());
    await waitFor(() => expect(result.current.items).toHaveLength(4));

    act(() => result.current.patchItems((row) => (row.id === 3 ? { id: 30 } : row)));

    expect(result.current.items.map((row) => row.id)).toEqual([1, 2, 30, 4]);
    expect(result.current.total).toBe(4);
    expect(fetchPage).toHaveBeenCalledTimes(2);
  });

  it("patching leaves an unrelated row untouched by identity", async () => {
    const fetchPage = vi.fn().mockResolvedValue(page([1, 2], 2));

    const { result } = renderHook(() => usePagedList<Row>(fetchPage, [], 2));
    await waitFor(() => expect(result.current.items).toHaveLength(2));
    const before = result.current.items[1];

    act(() => result.current.patchItems((row) => (row.id === 1 ? { id: 11 } : row)));

    expect(result.current.items[1]).toBe(before);
  });
});

