import { useCallback, useMemo, useState } from "react";
import Box from "@mui/material/Box";
import Button from "@mui/material/Button";
import Stack from "@mui/material/Stack";
import Tab from "@mui/material/Tab";
import Tabs from "@mui/material/Tabs";
import { Link as RouterLink } from "react-router-dom";

import * as api from "../api";
import CaseCard from "../components/feed/CaseCard";
import MySummonsPanel from "../components/trial/MySummonsPanel";
import { EmptyState, ErrorNote, Loading } from "../components/common/StateViews";
import InfiniteScroll from "../components/common/InfiniteScroll";
import { usePagedList } from "../hooks/usePagedList";
import { useAuth } from "../context/AuthContext";
import type { Case, CaseStatus } from "../types";

const PAGE_SIZE = 10;

interface FeedTab {
  id: string;
  label: string;
  /** One tab may cover several phases; see the decided tab below. */
  status?: CaseStatus[];
  /** The personal feed reads a different endpoint and sorts by activity. */
  mine?: boolean;
}

const FILTERS: FeedTab[] = [
  { id: "all", label: "הכול" },
  { id: "witness_phase", label: "איסוף עדויות", status: ["witness_phase"] },
  { id: "jury_deliberation", label: "דיוני מושבעים", status: ["jury_deliberation"] },
  // "Decided" is both statuses a verdict can leave a case in. A case sits in
  // `verdict_reached` only until the worker retires it, and then moves to
  // `closed` - so a tab that asked for `verdict_reached` alone showed the last
  // few hours of judgments and hid every case the court had actually finished,
  // which is the opposite of what a reader opening it wants.
  { id: "verdict_reached", label: "הוכרעו", status: ["verdict_reached", "closed"] },
];

const MY_FEED: FeedTab = { id: "mine", label: "הפיד שלי", mine: true };

const Feed = () => {
  const { user } = useAuth();

  /**
   * The open tab is tracked by id rather than by index, and starts on the
   * courtroom rather than on the personal feed.
   *
   * By id, because `user` resolves a moment after mount: the personal feed
   * appears in FRONT of the list when it does, and an index would quietly come
   * to mean the tab next door. By id it means the same tab throughout, and
   * signing out - which takes the personal feed away entirely - falls back to
   * the courtroom instead of pointing at nothing.
   *
   * On the courtroom, because a new account follows nothing yet, and landing
   * every signed-in visitor on an empty state to reach a feature they have not
   * used is a poor trade for one tap.
   */
  const [activeId, setActiveId] = useState(FILTERS[0].id);

  const tabs = useMemo(() => (user ? [MY_FEED, ...FILTERS] : FILTERS), [user]);
  const index = Math.max(
    tabs.findIndex((candidate) => candidate.id === activeId),
    0,
  );
  const active = tabs[index];

  const loadPage = useCallback(
    async (offset: number, limit: number) => {
      const page = active.mine
        ? await api.fetchMyFeed({ limit, offset })
        : await api.fetchCases({ limit, offset, status: active.status });
      return { items: page.cases, total: page.total };
    },
    [active],
  );
  const {
    items: cases,
    error,
    loading,
    hasMore,
    loadMore,
    patchItems,
  } = usePagedList(loadPage, [active], PAGE_SIZE);

  /**
   * A card reporting that the viewer liked or followed it.
   *
   * The list owns the rows, so the list is what rewrites one - in place, with
   * the totals the server itself returned. Refetching the page instead would
   * be a network round trip and a scroll back to the top to redraw one number,
   * and on the personal feed it would be worse than that: following a case
   * changes which rows belong there at all, so a refetch could move or remove
   * the very card the reader just tapped.
   */
  const patchCase = useCallback(
    (id: number, patch: Partial<Case>) => {
      patchItems((item) => (item.id === id ? { ...item, ...patch } : item));
    },
    [patchItems],
  );

  return (
    // Pulled up against the top bar. The shared Container's `py: 3` is right
    // for a page that opens with a heading; this one opens with a control
    // strip, and the full gap left it floating.
    <Box sx={{ mt: -2 }}>
      {/* Above everything: a summons you have not answered is the most
          time-critical thing on this page. */}
      {user && <MySummonsPanel />}

      {/* Tabs and the file-a-lawsuit button share one line: they are the only
          two controls on the page, and stacking them cost a whole row of empty
          space between the top bar and the first case. */}
      <Stack
        direction="row"
        alignItems="center"
        justifyContent="space-between"
        spacing={1}
        sx={{ mb: 2 }}
      >
        <Tabs
          value={index}
          onChange={(_, next) => setActiveId(tabs[next].id)}
          variant="scrollable"
          scrollButtons="auto"
          // minWidth lets the scroller shrink instead of shoving the button
          // off the row on a narrow screen.
          sx={{ flex: 1, minWidth: 0 }}
        >
          {tabs.map((filter) => (
            <Tab key={filter.id} label={filter.label} />
          ))}
        </Tabs>
        {user && (
          <Button
            variant="contained"
            color="secondary"
            component={RouterLink}
            to="/cases/new"
            sx={{ flexShrink: 0 }}
          >
            הגש תביעה
          </Button>
        )}
      </Stack>

      {error && <ErrorNote message={error} />}
      {loading && cases.length === 0 && <Loading label="טוען תיקים…" />}

      {!loading && cases.length === 0 && !error && active.mine && (
        <EmptyState
          title="אינך עוקב עדיין אחרי אף תביעה"
          description="עקוב אחרי תיק כדי לראות כאן כל תגובה, עדות והכרעה לפי סדר הזמן."
        />
      )}

      {!loading && cases.length === 0 && !error && !active.mine && (
        <EmptyState
          title="אין תיקים להצגה"
          description={
            active.status
              ? "נסה מסנן אחר."
              : "היכל המשפט ריק כרגע. אולי כדאי להגיש את התביעה הראשונה?"
          }
          action={
            user ? (
              <Button variant="contained" component={RouterLink} to="/cases/new">
                הגש תביעה
              </Button>
            ) : undefined
          }
        />
      )}

      {cases.map((c) => (
        <CaseCard
          key={c.id}
          case={c}
          showActivity={active.mine}
          canFollow={Boolean(user)}
          onChange={(patch) => patchCase(c.id, patch)}
        />
      ))}

      <InfiniteScroll
        hasMore={hasMore}
        loading={loading}
        onLoadMore={loadMore}
        label="טען עוד תיקים"
        testId="feed-load-more"
      />
    </Box>
  );
}; export default Feed;

client/src/pages/ForgotPassword.tsx:
import { useState } from "react";
import Alert from "@mui/material/Alert";
import Button from "@mui/material/Button";
import Link from "@mui/material/Link";
import Paper from "@mui/material/Paper";
import Stack from "@mui/material/Stack";
import TextField from "@mui/material/TextField";
import Typography from "@mui/material/Typography";
import { Link as RouterLink } from "react-router-dom";

import * as api from "../api";

const ForgotPassword = () => {
  const [email, setEmail] = useState("");
  const [sent, setSent] = useState(false);
  const [busy, setBusy] = useState(false);

  const submit = async (event: React.FormEvent) => {
    event.preventDefault();
    setBusy(true);
    try {
      await api.requestPasswordReset(email.trim());
    } finally {
      // The server answers identically whether or not the address is
      // registered, and so does this page — otherwise the UI would leak
      // exactly what the API is careful not to.
      setSent(true);
      setBusy(false);
    }
  };

  return (
    <Paper sx={{ p: { xs: 2, sm: 3 }, maxWidth: 440, mx: "auto" }} component="form" onSubmit={submit}>
      <Typography variant="h4" gutterBottom>
        איפוס סיסמה
      </Typography>

      {sent ? (
        <Stack spacing={2}>
          <Alert severity="success" data-testid="reset-requested">
            אם הכתובת רשומה במערכת, נשלח אליה קישור לאיפוס הסיסמה. הקישור תקף ל-30 דקות.
          </Alert>
          <Typography variant="body2" color="text.secondary">
            לא הגיע? כדאי לבדוק גם בתיקיית הספאם.
          </Typography>
          <Link component={RouterLink} to="/login">
            חזרה לכניסה
          </Link>
        </Stack>
      ) : (
        <Stack spacing={2}>
          <Typography color="text.secondary">
            הזן את כתובת האימייל שלך ונשלח אליך קישור לבחירת סיסמה חדשה.
          </Typography>
          <TextField
            label="אימייל"
            type="email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            required
            fullWidth
            autoComplete="email"
            inputProps={{ "data-testid": "forgot-email" }}
          />
          <Button type="submit" variant="contained" disabled={busy} data-testid="forgot-submit">
            {busy ? "שולח…" : "שלח קישור לאיפוס"}
          </Button>
          <Typography variant="body2" align="center">
            <Link component={RouterLink} to="/login">
              חזרה לכניסה
            </Link>
          </Typography>
        </Stack>
      )}
    </Paper>
  );
}; export default ForgotPassword;

client/src/pages/Login.tsx:
import { useState } from "react";
import Button from "@mui/material/Button";
import Link from "@mui/material/Link";
import Paper from "@mui/material/Paper";
import Stack from "@mui/material/Stack";
import TextField from "@mui/material/TextField";
import Typography from "@mui/material/Typography";
import { Link as RouterLink, Navigate, useLocation, useNavigate } from "react-router-dom";

import { ErrorNote } from "../components/common/StateViews";
import { useAuth } from "../context/AuthContext";

const Login = () => {
  const { user, signIn } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();

  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  if (user) return <Navigate to="/" replace />;

  const submit = async (event: React.FormEvent) => {
    event.preventDefault();
    setError(null);
    setBusy(true);
    try {
      await signIn(email.trim(), password);
      // Return the user to whatever they were trying to reach.
      navigate((location.state as { from?: string })?.from ?? "/", { replace: true });
    } catch (err) {
      setError(err instanceof Error ? err.message : "ההתחברות נכשלה.");
      setBusy(false);
    }
  };

  return (
    <Paper sx={{ p: { xs: 2, sm: 3 }, maxWidth: 440, mx: "auto" }} component="form" onSubmit={submit}>
      <Typography variant="h4" gutterBottom>
        כניסה
      </Typography>

      {error && <ErrorNote message={error} />}

      <Stack spacing={2}>
        <TextField
          label="אימייל"
          type="email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          required
          fullWidth
          autoComplete="email"
          inputProps={{ "data-testid": "login-email" }}
        />
        <TextField
          label="סיסמה"
          type="password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          required
          fullWidth
          autoComplete="current-password"
          inputProps={{ "data-testid": "login-password" }}
        />
        <Button
          type="submit"
          variant="contained"
          size="large"
          disabled={busy}
          data-testid="login-submit"
        >
          {busy ? "מתחבר…" : "כניסה"}
        </Button>

        <Typography variant="body2" align="center">
          <Link component={RouterLink} to="/forgot-password">
            שכחתי סיסמה
          </Link>
        </Typography>
        <Typography variant="body2" align="center" color="text.secondary">
          אין לך חשבון? <Link component={RouterLink} to="/signup">הרשמה</Link>
        </Typography>
      </Stack>
    </Paper>
  );
}; export default Login;

