import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import Avatar from "@mui/material/Avatar";
import Badge from "@mui/material/Badge";
import Box from "@mui/material/Box";
import Divider from "@mui/material/Divider";
import IconButton from "@mui/material/IconButton";
import List from "@mui/material/List";
import ListItemButton from "@mui/material/ListItemButton";
import Paper from "@mui/material/Paper";
import Stack from "@mui/material/Stack";
import TextField from "@mui/material/TextField";
import Typography from "@mui/material/Typography";
import ArrowForwardIcon from "@mui/icons-material/ArrowForward";
import SendIcon from "@mui/icons-material/Send";
import SmartToyIcon from "@mui/icons-material/SmartToy";
import { useSearchParams } from "react-router-dom";

import * as api from "../api";
import { EmptyState, ErrorNote, Loading } from "../components/common/StateViews";
import { useAsync } from "../hooks/useAsync";
import { useNotifications } from "../context/NotificationContext";
import type { Conversation, Message, UserRef } from "../types";
import { initials, relativeTime } from "../utils/format";

/**
 * The inbox: conversations on one side, the open thread on the other.
 *
 * There is no polling here. New messages arrive as `message` notifications on
 * the stream the bell already listens to, so this page reloads off the same
 * transport rather than opening a second one — and it still works when the
 * stream has fallen back to polling, because both paths land in the same
 * context.
 */
const Messages = () => {
  const [params, setParams] = useSearchParams();
  const { notifications } = useNotifications();

  const conversations = useAsync(api.fetchConversations, []);
  const [activeId, setActiveId] = useState<number | null>(null);
  /**
   * Somebody we are about to write to for the first time. There is no
   * conversation row yet and there must not be one until a message is
   * actually sent, so the thread pane composes against this instead.
   */
  const [pending, setPending] = useState<UserRef | null>(null);
  const [thread, setThread] = useState<Message[]>([]);
  const [threadError, setThreadError] = useState<string | null>(null);
  const [draft, setDraft] = useState("");
  const [sending, setSending] = useState(false);
  const bottom = useRef<HTMLDivElement | null>(null);

  const list = conversations.data?.conversations ?? [];
  const existing = list.find((c) => c.id === activeId) ?? null;

  // One shape for both cases, so the pane below does not care which it has.
  const active = existing
    ? { id: existing.id as number | null, other: existing.other }
    : pending
      ? { id: null as number | null, other: pending }
      : null;

  // Reloading the inbox is needed by three different effects; a ref keeps them
  // honest about their dependencies without re-running whenever useAsync hands
  // back a new function identity.
  const reloadConversations = conversations.reload;
  const reloadRef = useRef(reloadConversations);
  reloadRef.current = reloadConversations;

  const openThread = useCallback(async (conversationId: number) => {
    setThreadError(null);
    try {
      setThread(await api.fetchThread(conversationId));
    } catch (err) {
      setThread([]);
      setThreadError(err instanceof Error ? err.message : "לא הצלחנו לטעון את השיחה.");
    }
  }, []);

  /**
   * `?to=<userId>` is how the rest of the app opens a conversation — from a
   * profile, or from a message notification. It resolves to an existing thread
   * when there is one and to an empty composer when there is not, then drops
   * itself from the URL so a refresh does not reopen it over whatever the user
   * has since selected.
   */
  const to = params.get("to");
  useEffect(() => {
    if (!to) return;
    let cancelled = false;
    void (async () => {
      try {
        const found = await api.findConversationWith(Number(to));
        if (cancelled) return;
        if (found.conversation_id === null) {
          setPending(found.recipient);
          setActiveId(null);
          setThread([]);
        } else {
          setPending(null);
          setActiveId(found.conversation_id);
          await reloadRef.current();
        }
      } catch (err) {
        if (!cancelled) setThreadError(err instanceof Error ? err.message : "לא הצלחנו לפתוח שיחה.");
      } finally {
        if (!cancelled) setParams({}, { replace: true });
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [to, setParams]);

  useEffect(() => {
    if (activeId === null) {
      setThread([]);
      return;
    }
    void openThread(activeId);
  }, [activeId, openThread]);

  // The newest message notification. Its id changing is the signal that
  // something arrived — for this thread or another one.
  const latestMessageNotification = useMemo(
    () => notifications.find((n) => n.type === "message")?.id ?? 0,
    [notifications],
  );
  const activeIdRef = useRef(activeId);
  activeIdRef.current = activeId;
  useEffect(() => {
    if (!latestMessageNotification) return;
    void reloadRef.current();
    const open = activeIdRef.current;
    if (open !== null) void openThread(open);
  }, [latestMessageNotification, openThread]);

  useEffect(() => {
    bottom.current?.scrollIntoView({ block: "nearest" });
  }, [thread]);

  const select = (conversationId: number) => {
    setPending(null);
    setActiveId(conversationId);
  };

  const send = async (event: React.FormEvent) => {
    event.preventDefault();
    const body = draft.trim();
    if (!body || !active?.other) return;

    setSending(true);
    setThreadError(null);
    try {
      // Sending is what creates the conversation, so the id comes back from
      // the response rather than from a row we made in advance.
      const { conversation_id } = await api.sendMessage(active.other.id, body);
      setDraft("");
      setPending(null);
      setActiveId(conversation_id);
      await Promise.all([openThread(conversation_id), reloadRef.current()]);
    } catch (err) {
      setThreadError(err instanceof Error ? err.message : "לא הצלחנו לשלוח את ההודעה.");
    } finally {
      setSending(false);
    }
  };

  if (conversations.loading && !conversations.data) return <Loading label="טוען את תיבת ההודעות…" />;
  if (conversations.error) return <ErrorNote message={conversations.error} />;

  return (
    <Stack
      direction={{ xs: "column", md: "row" }}
      spacing={2}
      alignItems="stretch"
      data-testid="messages-page"
    >
      {/* Below md only one pane is on screen at a time: the list, or the
          thread the user picked from it. */}
      <Paper
        sx={{
          width: { xs: "100%", md: 300 },
          flexShrink: 0,
          display: { xs: active ? "none" : "block", md: "block" },
          overflow: "hidden",
        }}
      >
        <Typography variant="h6" sx={{ px: 2, py: 1.5 }}>
          הודעות
        </Typography>
        <Divider />

        {list.length === 0 ? (
          <EmptyState
            title="אין עדיין שיחות"
            description="אפשר לפתוח שיחה מהפרופיל של כל אדם בחצר."
          />
        ) : (
          <List disablePadding sx={{ maxHeight: { md: "60vh" }, overflowY: "auto" }}>
            {list.map((conversation) => (
              <ConversationRow
                key={conversation.id}
                conversation={conversation}
                selected={conversation.id === activeId}
                onSelect={() => select(conversation.id)}
              />
            ))}
          </List>
        )}
      </Paper>

      <Paper
        sx={{
          flex: 1,
          minWidth: 0,
          display: { xs: active ? "flex" : "none", md: "flex" },
          flexDirection: "column",
        }}
        data-testid="message-thread"
      >
        {active ? (
          <>
            <Stack direction="row" spacing={1} alignItems="center" sx={{ px: 2, py: 1.5 }}>
              <IconButton
                onClick={() => {
                  setActiveId(null);
                  setPending(null);
                }}
                sx={{ display: { xs: "inline-flex", md: "none" } }}
                aria-label="חזרה לרשימה"
              >
                <ArrowForwardIcon />
              </IconButton>
              <Avatar src={active.other?.avatar_url ?? undefined} sx={{ width: 32, height: 32 }}>
                {initials(active.other?.name ?? "?")}
              </Avatar>
              <Typography variant="subtitle1" fontWeight={700} noWrap sx={{ flex: 1 }}>
                {active.other?.name ?? "משתמש שנמחק"}
              </Typography>
              {active.other?.is_bot && <SmartToyIcon fontSize="small" color="disabled" />}
            </Stack>
            <Divider />

            <Box
              sx={{
                flex: 1,
                overflowY: "auto",
                px: 2,
                py: 2,
                minHeight: { xs: 240, md: "45vh" },
                maxHeight: { md: "45vh" },
              }}
            >
              {thread.length === 0 && !threadError && (
                <Typography color="text.secondary" align="center">
                  עוד לא נאמר כאן דבר. תתחיל/י.
                </Typography>
              )}
              <Stack spacing={1}>
                {thread.map((message) => (
                  <Bubble key={message.id} message={message} />
                ))}
              </Stack>
              <div ref={bottom} />
            </Box>

            <Divider />
            <Box component="form" onSubmit={send} sx={{ p: 1.5 }}>
              {threadError && <ErrorNote message={threadError} />}
              <Stack direction="row" spacing={1} alignItems="flex-end">
                <TextField
                  value={draft}
                  onChange={(e) => setDraft(e.target.value)}
                  placeholder="כתוב/י הודעה…"
                  multiline
                  maxRows={4}
                  fullWidth
                  size="small"
                  inputProps={{ "data-testid": "message-body", maxLength: 2000 }}
                  onKeyDown={(e) => {
                    // Enter sends; Shift+Enter is a newline, as everywhere else.
                    if (e.key === "Enter" && !e.shiftKey) {
                      e.preventDefault();
                      void send(e as unknown as React.FormEvent);
                    }
                  }}
                />
                <IconButton
                  type="submit"
                  color="primary"
                  disabled={sending || !draft.trim()}
                  aria-label="שליחה"
                  data-testid="message-send"
                >
                  <SendIcon />
                </IconButton>
              </Stack>
            </Box>
          </>
        ) : (
          <EmptyState title="בחר/י שיחה" description="הרשימה מימין מרכזת את כל ההתכתבויות." />
        )}
      </Paper>
    </Stack>
  );
}; export default Messages;

const ConversationRow = ({
  conversation,
  selected,
  onSelect,
}: {
  conversation: Conversation;
  selected: boolean;
  onSelect: () => void;
}) => {
  return (
    <ListItemButton
      selected={selected}
      onClick={onSelect}
      data-testid="conversation-row"
      sx={{ alignItems: "flex-start", gap: 1.5 }}
    >
      <Badge
        color="secondary"
        badgeContent={conversation.unread_count}
        max={9}
        overlap="circular"
        anchorOrigin={{ vertical: "top", horizontal: "left" }}
      >
        <Avatar src={conversation.other?.avatar_url ?? undefined} sx={{ width: 36, height: 36 }}>
          {initials(conversation.other?.name ?? "?")}
        </Avatar>
      </Badge>

      <Box sx={{ minWidth: 0, flex: 1 }}>
        <Typography variant="subtitle2" noWrap fontWeight={conversation.unread_count ? 700 : 500}>
          {conversation.other?.name ?? "משתמש שנמחק"}
        </Typography>
        <Typography variant="body2" color="text.secondary" noWrap>
          {conversation.last_message?.body ?? "—"}
        </Typography>
        <Typography variant="caption" color="text.secondary">
          {relativeTime(conversation.last_message?.created_at ?? null)}
        </Typography>
      </Box>
    </ListItemButton>
  );
};

const Bubble = ({ message }: { message: Message }) => {
  return (
    <Box
      data-testid="message-bubble"
      data-mine={message.is_mine}
      sx={{
        // The stack is a column, so alignSelf is the horizontal axis. Under
        // RTL `flex-end` is the left edge — where a Hebrew chat app puts the
        // messages you sent.
        alignSelf: message.is_mine ? "flex-end" : "flex-start",
        maxWidth: "80%",
        px: 1.5,
        py: 1,
        borderRadius: 2,
        bgcolor: message.is_mine ? "primary.main" : "action.hover",
        color: message.is_mine ? "primary.contrastText" : "text.primary",
      }}
    >
      <Typography variant="body2" sx={{ whiteSpace: "pre-wrap", wordBreak: "break-word" }}>
        {message.body}
      </Typography>
      <Typography
        variant="caption"
        sx={{ display: "block", mt: 0.25, opacity: 0.7, textAlign: "start" }}
      >
        {relativeTime(message.created_at)}
      </Typography>
    </Box>
  );
};

client/src/pages/NewCase.tsx:
import { useState } from "react";
import Autocomplete from "@mui/material/Autocomplete";
import Box from "@mui/material/Box";
import Button from "@mui/material/Button";
import Chip from "@mui/material/Chip";
import Paper from "@mui/material/Paper";
import Stack from "@mui/material/Stack";
import TextField from "@mui/material/TextField";
import Typography from "@mui/material/Typography";
import { useNavigate } from "react-router-dom";

import * as api from "../api";
import AssistButton from "../components/assist/AssistButton";
import ImageUploadField from "../components/common/ImageUploadField";
import { ErrorNote } from "../components/common/StateViews";
import { CHARGE_SUGGESTIONS } from "../types";
import type { User } from "../types";

const NewCase = () => {
  const navigate = useNavigate();

  const [title, setTitle] = useState("");
  const [body, setBody] = useState("");
  const [defendantText, setDefendantText] = useState("");
  const [charges, setCharges] = useState<string[]>([]);
  const [imageUrl, setImageUrl] = useState("");
  const [defendantUser, setDefendantUser] = useState<User | null>(null);
  const [candidates, setCandidates] = useState<User[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);

  const searchDefendants = async (text: string) => {
    if (text.trim().length < 2) {
      setCandidates([]);
      return;
    }
    try {
      const { users } = await api.fetchUsers({ search: text, limit: 8 });
      setCandidates(users);
    } catch {
      setCandidates([]);
    }
  };

  const submit = async (event: React.FormEvent) => {
    event.preventDefault();
    setError(null);
    setSaving(true);
    try {
      const created = await api.createCase({
        title,
        body,
        defendant_text: defendantText || defendantUser?.name || "",
        defendant_user_id: defendantUser?.id ?? null,
        charges,
        image_url: imageUrl || null,
      });
      navigate(`/cases/${created.id}`);
    } catch (err) {
      setError(err instanceof Error ? err.message : "לא הצלחנו להגיש את התביעה.");
      setSaving(false);
    }
  };

  return (
    <Paper sx={{ p: { xs: 2, sm: 3 } }} component="form" onSubmit={submit}>
      <Typography variant="h4" gutterBottom>
        הגשת תביעה
      </Typography>
      <Typography color="text.secondary" sx={{ mb: 3 }}>
        אפשר לתבוע משתמש רשום — ואז גם הוא יוכל לזמן עדים — או כל דבר אחר בעולם, למשל "יום שני".
      </Typography>

      {error && <ErrorNote message={error} />}

      <Stack spacing={2.5}>
        <TextField
          label="כותרת התביעה"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          required
          fullWidth
          helperText="לדוגמה: התביעה נגד יום שני"
          inputProps={{ "data-testid": "case-title", maxLength: 512 }}
        />

        <Autocomplete
          options={candidates}
          value={defendantUser}
          getOptionLabel={(option) => option.name}
          onInputChange={(_, text) => void searchDefendants(text)}
          onChange={(_, value) => {
            setDefendantUser(value);
            if (value) setDefendantText(value.name);
          }}
          isOptionEqualToValue={(a, b) => a.id === b.id}
          noOptionsText="לא נמצאו משתמשים"
          renderInput={(params) => (
            <TextField
              {...params}
              label="נתבע רשום (אופציונלי)"
              helperText="השאר ריק כדי לתבוע משהו שאינו משתמש"
            />
          )}
        />

        <TextField
          label="נגד מי התביעה"
          value={defendantText}
          onChange={(e) => setDefendantText(e.target.value)}
          required
          fullWidth
          inputProps={{ "data-testid": "case-defendant", maxLength: 255 }}
        />

        <Autocomplete
          multiple
          freeSolo
          options={[...CHARGE_SUGGESTIONS]}
          value={charges}
          onChange={(_, value) => setCharges(value.slice(0, 5))}
          renderTags={(value, getTagProps) =>
            value.map((option, index) => (
              <Chip label={option} size="small" {...getTagProps({ index })} key={option} />
            ))
          }
          renderInput={(params) => (
            <TextField {...params} label="סעיפי האישום" helperText="עד חמישה סעיפים" />
          )}
        />

        <ImageUploadField
          label="ראיה חזותית (אופציונלי)"
          helper="JPG, PNG, GIF או WEBP, עד 5 מגה-בייט. התמונה תוצג בראש התיק."
          value={imageUrl}
          onChange={setImageUrl}
          disabled={saving}
        />

        <Box>
          <TextField
            label="כתב התביעה"
            value={body}
            onChange={(e) => setBody(e.target.value)}
            required
            multiline
            minRows={6}
            fullWidth
            inputProps={{ "data-testid": "case-body", maxLength: 8000 }}
          />
          <Box sx={{ display: "flex", justifyContent: "flex-end", gap: 1, mt: 1 }}>
            {/* Two different offers, and keeping them apart is the point: the
                drafter writes a filing from the details, the proofreader only
                fixes what the user already wrote. One button doing both would
                mean every request for a spelling check came back as somebody
                else's lawsuit. Hence the second one is disabled until there is
                text of the user's own to correct. */}
            <AssistButton
              size="small"
              label="תקן לי את הניסוח"
              title="תיקון כתב התביעה"
              helper="בית המשפט יתקן שגיאות כתיב, דקדוק ופיסוק — בלי לשנות את מה שכתבת. הטקסט המתוקן יחזור לכאן לאישורך."
              disabled={!body.trim()}
              load={() => api.correctText(body)}
              onAccept={setBody}
              acceptLabel="החלף בטקסט המתוקן"
              busyLabel="מתקן…"
              retryLabel="תקן שוב"
              offlineNote="המנוע המקומי אינו יודע לתקן עברית, ולכן הטקסט הוחזר כפי שהוא. תיקון אמיתי דורש חיבור למודל שפה."
            />
            {/* Needs at least a defendant — the drafter has nothing to write
                about otherwise, and the endpoint says so with a 400. */}
            <AssistButton
              size="small"
              label="נסח לי את התביעה"
              title="ניסוח כתב התביעה"
              helper="מנסח בית המשפט יכתוב טיוטה מהפרטים שמילאת. אפשר לערוך אותה לפני ההגשה."
              disabled={!defendantText.trim() && !title.trim()}
              load={() =>
                api.draftLawsuit({
                  defendant_text: defendantText,
                  title,
                  charges,
                  hint: body,
                })
              }
              onAccept={setBody}
              acceptLabel="הכנס לכתב התביעה"
            />
          </Box>
        </Box>

        <Box sx={{ display: "flex", gap: 1, justifyContent: "flex-end" }}>
          <Button onClick={() => navigate(-1)} disabled={saving}>
            ביטול
          </Button>
          <Button
            type="submit"
            variant="contained"
            color="secondary"
            disabled={saving}
            data-testid="case-submit"
          >
            {saving ? "מגיש…" : "הגש לבית המשפט"}
          </Button>
        </Box>
      </Stack>
    </Paper>
  );
}; export default NewCase;

