"""The ops half of the admin dashboard: AI usage and the site overview tiles.

Split from moderation.py because these endpoints answer a different question -
not "what needs a human's judgment" but "is the machinery healthy" - even
though both sit behind the same `require_admin` gate and the same dashboard.
System health itself is not here: `GET /api/health` already answers it and is
already unauthenticated, so the admin UI calls that endpoint directly rather
than through a second, admin-gated copy of the same data.
"""

from __future__ import annotations

from flask import Blueprint, jsonify

from .. import security
from ..services import brain_usage_service, cases_service, moderation_service, users_service

bp = Blueprint("admin_ops", __name__)

# Every case status except 'closed' - a case is "active" for as long as the
# trial engine still has something left to do with it.
_OPEN_CASE_STATUSES = tuple(s for s in cases_service.CASE_STATUSES if s != "closed")


@bp.get("/admin/brain/usage")
@security.require_admin
def admin_brain_usage():
    return jsonify(
        {
            "today": brain_usage_service.usage_today(),
            "week": brain_usage_service.usage_this_week(),
            # Per KEY, not per vendor. Quota belongs to a credential and a
            # model, so "Gemini is at 900" says nothing useful once there is
            # more than one key - it is the one that is exhausted that matters.
            "credentials": brain_usage_service.credential_quotas(),
            "by_credential": brain_usage_service.usage_by_credential(),
            "by_credential_week": brain_usage_service.usage_by_credential(days=7),
            # Why calls are failing, not just how many. Without this the tab
            # cannot tell "near the quota" apart from "every call is erroring",
            # which are the same picture and completely different problems.
            "failures": brain_usage_service.recent_failures(),
        }
    ), 200


@bp.get("/admin/overview")
@security.require_admin
def admin_overview():
    return jsonify(
        {
            "total_users": users_service.count_users(include_bots=False, status="active"),
            "open_cases": cases_service.count_cases(status=_OPEN_CASE_STATUSES),
            "pending_reports": moderation_service.count_reports(status="pending"),
            "banned_users": users_service.count_users(status="banned"),
        }
    ), 200

server/app/api/assist.py:
"""AI writing help.

The same `generate()` the jurors use, pointed at the user's own composer. With
no API key configured this is the deterministic offline generator, so the
feature works in a fresh checkout with nothing set up - which is the whole
reason the offline path is the default rather than a fallback.

Nothing here writes to the database. A suggestion is a suggestion: the user
still has to submit it, and it is screened at publish time like any other text.
"""

from __future__ import annotations

from flask import Blueprint, g, jsonify, request

from .. import brain, security
from ..errors import fail
from ..services import agents_service, cases_service
from ..validation import body_of, clean
from .cases import BODY_MAX_LENGTH

bp = Blueprint("assist", __name__)

# The house style for writing help. This is a character sheet like every
# personality in seed_data, and for the same reason: one line of description
# ("florid and theatrical") produced one register, so every suggestion the
# composer offered came out sounding like the last one.
HOUSE_VOICE = (
    "אתה עוזר הניסוח הרשמי של בית המשפט לתביעות מצחיקות. תפקידך לקחת תלונה "
    "קטנה ולהלביש אותה בשפה משפטית רצינית להפליא.\n\n"
    "**איך אתה כותב:** עברית משפטית גבוהה, מדויקת וחגיגית, בשירות עניין "
    "פעוט לחלוטין. הפער בין הצורה לתוכן הוא כל הבדיחה.\n"
    "**סימני היכר:** מנסח סעיפים כאילו הם מצוטטים מחוק קיים. מתאר רגעים "
    "יומיומיים בלשון של פרוטוקול. נוקב בפרטים מדויקים להחריד.\n"
    "**מה מפעיל אותך:** תלונה מנוסחת ברישול, שאפשר להפוך לכתב תביעה מהודר.\n"
    "**מה שלא תעשה לעולם:** תקרוץ לקורא או תרמוז שזה מצחיק. אתה רציני לגמרי.\n\n"
    "**ככה אתה נשמע:**\n"
    '- "מוגשת בזאת תביעה בעניינה של מדבקת מחיר אשר סירבה לרדת בשלמותה."\n'
    '- "התובע יטען כי המעשה בוצע ביודעין, בשעה 7:04, ובלא כל התראה מוקדמת."\n'
    '- "מתבקש בית המשפט הנכבד להורות על השבת המצב לקדמותו, ולמצער על התנצלות בכתב."'
)


# And the house proofreader, who is emphatically not the house drafter.
#
# HOUSE_VOICE above is a *rewriter*: hand it a shabby complaint and it hands
# back a filing in ceremonial legal Hebrew, which is precisely what
# /assist/draft-lawsuit is for. Pointed at text the user has already written it
# does the same thing and calls the result a correction - the user gets back
# prose they did not write, in a register they did not choose, with their own
# jokes ironed out. The two endpoints would have collapsed into one.
#
# So correction gets its own character sheet, and the whole of that character
# is restraint. The task brief in brain/llm/prompt.py carries the hard rules; this
# block is what the model is being, and it is being a person who does not write.
PROOFREADER_VOICE = (
    "אתה המגיה של בית המשפט. אתה מתקן עברית, אתה לא כותב עברית.\n\n"
    "**מה אתה עושה:** כתיב, דקדוק, התאמות, מילות יחס, פיסוק. בשקט, בדיוק, "
    "בלי חוות דעת ובלי הערות שוליים.\n"
    "**מה מפעיל אותך:** שגיאה. רק שגיאה.\n"
    "**מה שלא תעשה לעולם:** תשכתב משפט תקין, תייפה ניסוח, תוסיף הומור, תוסיף "
    "לשון משפטית, או תיגע במילה שאין בה שגיאה. הטקסט שייך למי שכתב אותו, "
    "והעבודה שלך היא שהוא ייראה בדיוק כפי שהתכוון."
)


@bp.post("/assist/draft-lawsuit")
@security.require_auth
def draft_lawsuit():
    """Draft a filing from whatever the user has typed so far."""
    data = body_of(request)
    defendant = clean(data.get("defendant_text"), 255)
    title = clean(data.get("title"), 512)
    hint = clean(data.get("hint"), 500)

    if not defendant and not title and not hint:
        return fail("invalid", "יש לציין לפחות נגד מי התביעה.")

    context = {
        "defendant": defendant or "הנתבע",
        "case_title": title or f"התביעה נגד {defendant}",
        "charges": cases_service.clean_charges(data.get("charges")),
        "case_body": hint,
    }
    return jsonify(
        {
            "body": brain.generate(HOUSE_VOICE, "draft_lawsuit", context, max_chars=700),
            "backend": "llm" if _live() else "offline",
        }
    ), 200


@bp.post("/assist/suggest-comment")
@security.require_auth
def suggest_comment():
    """Suggest a comment for a case the user is looking at."""
    data = body_of(request)
    try:
        case_id = int(data.get("case_id"))
    except (TypeError, ValueError):
        return fail("invalid", "התיק אינו תקין.")

    case = cases_service.get_case(case_id, viewer_id=g.user_id)
    if case is None:
        return fail("not_found", "התיק המבוקש לא נמצא.")

    context = {
        "case_title": case["title"],
        "case_body": (case["body"] or "")[:600],
        "defendant": case["defendant_text"],
        "charges": case["charges"],
    }
    return jsonify(
        {
            "body": brain.generate(HOUSE_VOICE, "suggest_comment", context, max_chars=280),
            "backend": "llm" if _live() else "offline",
        }
    ), 200


@bp.post("/assist/correct-text")
@security.require_auth
def correct_text():
    """Hand back what the user wrote, spelled and punctuated properly.

    The third of the spec's writing-help endpoints, and the one that is not
    writing: /assist/draft-lawsuit invents a filing and /assist/suggest-comment
    invents a comment, while this one is given text that already exists and
    must give the same text back. Everything about it - a proofreader instead
    of the house voice, no seeded angle, no `tidy` on the way out - exists to
    stop it drifting into being a third drafter.

    Nothing is published here. The corrected text goes back into the composer
    the user was already filling in, and reaches the database through the
    ordinary publish path, moderation scan included, exactly like text they
    typed themselves.
    """
    data = body_of(request)
    # BODY_MAX_LENGTH is the longest thing any composer on the site can hold (a
    # filing; a comment is shorter). Capping at anything less would silently
    # drop the end of a long filing and return the truncation as a correction.
    text = clean(data.get("text"), BODY_MAX_LENGTH)

    if not text:
        return fail("invalid", "אין טקסט לתיקון.")

    corrected = brain.generate(
        PROOFREADER_VOICE,
        "correct_text",
        {"user_text": text},
        # Derived from the input rather than pinned, because a correction is as
        # long as the thing it corrects. A fixed budget - the 700 the drafter
        # uses - would cap the model mid-filing, and the truncation would look
        # like the proofreader having deleted the user's last two paragraphs.
        # `_max_tokens_for` doubles this again for Hebrew and for thinking.
        max_chars=len(text) + 200,
    )

    return jsonify(
        {
            # The same ceiling the input was held to: a model that loops must
            # not hand the composer more text than the composer can submit.
            "body": clean(corrected, BODY_MAX_LENGTH),
            "backend": "llm" if _live() else "offline",
        }
    ), 200


@bp.post("/assist/in-character")
@security.require_auth
def in_character():
    """Rewrite in the voice of one of the court's personalities - the same
    seam the bots use, exposed for fun."""
    data = body_of(request)
    hint = clean(data.get("hint"), 500)
    try:
        agent_id = int(data.get("agent_user_id"))
    except (TypeError, ValueError):
        return fail("invalid", "יש לבחור דמות.")

    agent = agents_service.get_agent(agent_id)
    if agent is None:
        return fail("not_found", "הדמות לא נמצאה.")

    return jsonify(
        {
            "body": brain.generate(
                agent["personality_prompt"], "suggest_comment", {"case_body": hint}, max_chars=280
            ),
            "personality_name": agent["personality_name"],
        }
    ), 200


def _live() -> bool:
    from ..config import get_settings

    return get_settings().use_llm

server/app/api/auth.py:
"""Signing up, signing in, signing out, and who am I."""

from __future__ import annotations

from flask import Blueprint, g, jsonify, request

from .. import mail, security
from ..config import get_settings
from ..errors import fail
from ..services import auth_service, users_service
from ..validation import body_of, clean, is_email, name_problem

bp = Blueprint("auth", __name__)


def _authenticated_response(user: dict, status: int = 200):
    """Mint a session and attach the cookie. The one place that happens."""
    settings = get_settings()
    raw_token = auth_service.create_session(user["id"], ttl_days=settings.session_ttl_days)
    response = jsonify({"user": users_service.private_user(user)})
    security.set_session_cookie(response, raw_token, settings)
    return response, status


@bp.post("/auth/signup")
def signup():
    data = body_of(request)
    name = clean(data.get("name"), 200)
    email = clean(data.get("email"), 320).lower()
    password = data.get("password") or ""

    if problem := name_problem(name):
        return fail("invalid", problem)
    if not is_email(email):
        return fail("invalid", "כתובת האימייל אינה תקינה.")
    # Checked before hashing: bcrypt 5 raises on anything over 72 bytes rather
    # than truncating it.
    if problem := security.password_problem(password):
        return fail("invalid", problem)

    result, user_id = users_service.create_user(
        name, email, security.hash_password(password)
    )
    if result == "conflict":
        return fail("conflict", "כתובת האימייל הזו כבר רשומה במערכת.")

    user = users_service.get_by_id(user_id)
    return _authenticated_response(user, status=201)


@bp.post("/auth/login")
def login():
    data = body_of(request)
    email = clean(data.get("email"), 320).lower()
    password = data.get("password") or ""

    user = users_service.get_by_email(email) if email else None

    # One message and one code for "no such account" and "wrong password", so
    # the endpoint cannot be used to discover which addresses are registered.
    if user is None or not security.verify_password(password, user["password_hash"]):
        return fail("unauthorized", "כתובת האימייל או הסיסמה שגויות.")

    if user["status"] == "banned":
        return fail("forbidden", "החשבון הזה הושעה על ידי בית המשפט.")

    return _authenticated_response(user)


@bp.post("/auth/logout")
def logout():
    """Always succeeds - signing out an already-invalid session is not an
    error, and reporting one would only strand the browser's cookie."""
    auth_service.delete_session(request.cookies.get(security.COOKIE_NAME))
    response = jsonify({"ok": True})
    security.clear_session_cookie(response)
    return response, 200


# --- password reset ---------------------------------------------------------
#
# Two endpoints. The first always answers the same way, so it cannot be used to
# discover which addresses are registered. The second spends the token exactly
# once and signs the account out everywhere.


@bp.post("/auth/password-reset/request")
def request_password_reset():
    data = body_of(request)
    email = clean(data.get("email"), 320).lower()

    # Deliberately identical for a known address, an unknown one, a banned
    # account and a malformed string.
    generic = jsonify(
        {"ok": True, "message": "אם הכתובת רשומה במערכת, נשלח אליה קישור לאיפוס הסיסמה."}
    ), 200

    if not is_email(email):
        return generic

    settings = get_settings()
    user = users_service.get_by_email(email)
    if user is None or user["status"] == "banned":
        return generic

    # Already sent one a moment ago. Still the generic answer - a "slow down"
    # here would tell an attacker the address is registered, which is exactly
    # what the rest of this endpoint refuses to say.
    if auth_service.reset_requested_recently(
        user["id"], settings.reset_cooldown_seconds
    ):
        return generic

    raw_token = auth_service.issue_password_reset(
        user["id"], ttl_minutes=settings.reset_ttl_minutes
    )

    reset_url = f"{settings.client_origin.rstrip('/')}/reset-password?token={raw_token}"
    mail.send_mail_async(
        to=user["email"],
        subject="איפוס סיסמה - LolSuit",
        body=mail.password_reset_body(user["name"], reset_url, settings.reset_ttl_minutes),
        html=mail.password_reset_html(user["name"], reset_url, settings.reset_ttl_minutes),
    )
    return generic


@bp.get("/auth/password-reset/validate")
def validate_password_reset():
    """Is this link still worth showing a form for?

    The page behind a reset link used to render the form for anything with a
    `token=` in the URL, so an expired or already-spent link only failed after
    the user had typed a new password twice. This answers before that.

    It spends nothing - `consume_password_reset` remains the only thing that
    does - and it says nothing the confirm endpoint does not already say:
    missing, forged, expired and spent all get one identical refusal, in the
    same words, and success carries no account details at all.
    """
    token = clean(request.args.get("token"), 200)

    if not token or not auth_service.password_reset_is_valid(token):
        return fail("invalid", "קישור האיפוס אינו תקף או שכבר נעשה בו שימוש.")

    return jsonify({"ok": True}), 200


@bp.post("/auth/password-reset/confirm")
def confirm_password_reset():
    data = body_of(request)
    token = clean(data.get("token"), 200)
    password = data.get("password") or ""

    if not token:
        return fail("invalid", "חסר טוקן איפוס.")
    if problem := security.password_problem(password):
        return fail("invalid", problem)

    result, _user_id = auth_service.reset_password(token, security.hash_password(password))
    if result != "ok":
        return fail("invalid", "קישור האיפוס אינו תקף או שכבר נעשה בו שימוש.")

    return jsonify({"ok": True, "message": "הסיסמה עודכנה. אפשר להתחבר מחדש."}), 200


@bp.get("/auth/me")
@security.optional_auth
def me():
    """Anonymous is a normal answer here, not an error: the front end calls
    this on load to decide what to render."""
    if g.user is None:
        return jsonify({"user": None}), 200
    return jsonify({"user": users_service.private_user(g.user)}), 200

server/app/api/cases.py:
"""Filing, browsing and withdrawing lawsuits."""

from __future__ import annotations

from flask import Blueprint, g, jsonify, request

from .. import security
from ..errors import fail
from ..services import cases_service, users_service
from ..validation import body_of, clean, positive_int

bp = Blueprint("cases", __name__)

MAX_PAGE_SIZE = 50
BODY_MAX_LENGTH = 8000
# Long enough for every status named at once, and no longer.
STATUS_PARAM_MAX_LENGTH = 128


@bp.get("/cases")
@security.optional_auth
def list_cases():
    """The feed. Works signed out; a signed-in viewer additionally learns which
    cases they have already liked."""
    limit = positive_int(request.args.get("limit"), 20, maximum=MAX_PAGE_SIZE)
    offset = positive_int(request.args.get("offset"), 0)
    author_id = request.args.get("author_id", type=int)

    # `status` may name several phases at once, comma separated - the feed's
    # "decided" tab wants verdict_reached AND closed, which are one thing to a
    # reader and two rows to the database.
    status = clean(request.args.get("status"), STATUS_PARAM_MAX_LENGTH)
    statuses = [value.strip() for value in status.split(",") if value.strip()]
    unknown = [value for value in statuses if value not in cases_service.CASE_STATUSES]
    if unknown:
        # Rejected rather than ignored: a mistyped filter that silently matches
        # nothing looks exactly like an empty court, and the client would have
        # no way to tell the two apart.
        return fail("invalid", "מסנן הסטטוס אינו תקין.")

    cases = cases_service.list_cases(
        viewer_id=g.user_id, author_id=author_id, status=statuses, limit=limit, offset=offset
    )
    total = cases_service.count_cases(author_id=author_id, status=statuses)
    return jsonify({"cases": cases, "total": total, "limit": limit, "offset": offset}), 200


@bp.get("/cases/feed")
@security.require_auth
def my_feed():
    """The viewer's own feed: what they follow, most recently active first.

    Signed-in only, and no `status` filter - the point of this list is "what
    has moved", which a phase filter would fight. Same envelope as /cases so
    the client pages it with the same hook.
    """
    limit = positive_int(request.args.get("limit"), 20, maximum=MAX_PAGE_SIZE)
    offset = positive_int(request.args.get("offset"), 0)

    cases = cases_service.list_followed_cases(g.user_id, limit=limit, offset=offset)
    total = cases_service.count_followed_cases(g.user_id)
    return jsonify({"cases": cases, "total": total, "limit": limit, "offset": offset}), 200


@bp.post("/cases")
@security.require_auth
def create_case():
    data = body_of(request)
    title = clean(data.get("title"), cases_service.TITLE_MAX_LENGTH)
    body = clean(data.get("body"), BODY_MAX_LENGTH)
    defendant_text = clean(data.get("defendant_text"), 255)
    image_url = clean(data.get("image_url"), 1024) or None
    defendant_user_id = data.get("defendant_user_id")

    if len(title) < 3:
        return fail("invalid", "כותרת התביעה קצרה מדי.")
    if len(body) < 10:
        return fail("invalid", "כתב התביעה קצר מדי.")

    if defendant_user_id is not None:
        try:
            defendant_user_id = int(defendant_user_id)
        except (TypeError, ValueError):
            return fail("invalid", "הנתבע שנבחר אינו תקין.")

        if defendant_user_id == g.user_id:
            return fail("invalid", "אי אפשר לתבוע את עצמך.")

        defendant = users_service.get_by_id(defendant_user_id)
        if defendant is None or defendant["status"] != "active":
            return fail("invalid", "הנתבע שנבחר אינו קיים.")
        # Keep the free-text field meaningful even when a real user is named,
        # so the card reads the same either way.
        defendant_text = defendant_text or defendant["name"]

    if not defendant_text:
        return fail("invalid", "יש לציין נגד מי מוגשת התביעה.")

    result, case_id = cases_service.create_case(
        g.user_id,
        title,
        body,
        defendant_text,
        defendant_user_id=defendant_user_id,
        charges=data.get("charges"),
        image_url=image_url,
    )
    if result == "rejected":
        # 422, not 400: the request was well-formed, we simply refuse to
        # publish it. The row exists for the admin queue but is never public.
        return fail("rejected", "כתב התביעה נחסם על ידי מנגנון סינון התוכן.")
    if result != "ok":
        return fail(result)

    case = cases_service.get_case(case_id, viewer_id=g.user_id)
    return jsonify({"case": case}), 201


@bp.get("/cases/<int:case_id>")
@security.optional_auth
def get_case(case_id: int):
    case = cases_service.get_case(
        case_id,
        viewer_id=g.user_id,
        viewer_is_admin=bool(g.user and g.user.get("is_admin")),
    )
    if case is None:
        return fail("not_found", "התיק המבוקש לא נמצא.")
    return jsonify({"case": case}), 200


@bp.delete("/cases/<int:case_id>")
@security.require_auth
def delete_case(case_id: int):
    result = cases_service.delete_case(case_id, g.user_id)
    if result == "not_found":
        return fail("not_found", "התיק המבוקש לא נמצא.")
    if result == "forbidden":
        return fail("forbidden", "רק מגיש התביעה יכול למשוך אותה.")
    if result == "closed":
        return fail("closed", "לא ניתן למשוך תביעה אחרי שהורכב הרכב מושבעים.")
    return jsonify({"ok": True}), 200

