"""Likes, follows and comments - the ordinary social surface of a case."""

from __future__ import annotations

from flask import Blueprint, g, jsonify, request

from .. import security
from ..errors import fail
from ..services import cases_service, comments_service, follows_service, likes_service
from ..validation import body_of, clean

bp = Blueprint("social", __name__)


@bp.post("/cases/<int:case_id>/like")
@security.require_auth
def toggle_like(case_id: int):
    """One endpoint for both directions: the server owns the current state, so
    the client cannot get out of step by guessing it."""
    result, payload = likes_service.toggle_like(case_id, g.user_id)
    if result != "ok":
        return fail("not_found", "התיק המבוקש לא נמצא.")
    return jsonify(payload), 200


@bp.post("/cases/<int:case_id>/follow")
@security.require_auth
def toggle_follow(case_id: int):
    """Both directions again, for the same reason the like endpoint is one."""
    result, payload = follows_service.toggle_follow(case_id, g.user_id)
    if result != "ok":
        return fail("not_found", "התיק המבוקש לא נמצא.")
    return jsonify(payload), 200


@bp.get("/cases/<int:case_id>/likes")
@security.optional_auth
def list_likers(case_id: int):
    """Who liked a case. Behind the same visibility rule as the case itself -
    a hidden filing must not leak its audience either."""
    case = cases_service.get_case(
        case_id,
        viewer_id=g.user_id,
        viewer_is_admin=bool(g.user and g.user.get("is_admin")),
    )
    if case is None:
        return fail("not_found", "התיק המבוקש לא נמצא.")
    return jsonify({"users": likes_service.likers(case_id)}), 200


@bp.get("/cases/<int:case_id>/followers")
@security.optional_auth
def list_followers(case_id: int):
    """Who tracks a case. Behind the same visibility rule as the likers list -
    a hidden filing must not leak its audience either."""
    case = cases_service.get_case(
        case_id,
        viewer_id=g.user_id,
        viewer_is_admin=bool(g.user and g.user.get("is_admin")),
    )
    if case is None:
        return fail("not_found", "התיק המבוקש לא נמצא.")
    return jsonify({"users": follows_service.followers(case_id)}), 200


@bp.get("/cases/<int:case_id>/comments")
@security.optional_auth
def list_comments(case_id: int):
    """The thread, behind the same visibility rule as the case itself.

    The guard is not redundant with `shape_comment`'s redaction, because the
    two answer different questions. Hiding a case does not cascade to its
    comments - the case row becomes 'hidden' and every comment on it stays
    'published' - and `shape_comment` decides redaction from the *comment's*
    own status, which is right for a hidden reply on a public case and says
    nothing at all about a public reply on a hidden one.

    Without this, a filing hidden for harassment kept the entire argument on it
    readable to anybody holding the case id, while `/likes` and `/followers`,
    which leak considerably less, were both closed.
    """
    case = cases_service.get_case(
        case_id,
        viewer_id=g.user_id,
        viewer_is_admin=bool(g.user and g.user.get("is_admin")),
    )
    if case is None:
        return fail("not_found", "התיק המבוקש לא נמצא.")

    comments = comments_service.list_for_case(
        case_id,
        viewer_id=g.user_id,
        viewer_is_admin=bool(g.user and g.user.get("is_admin")),
    )
    return jsonify({"comments": comments}), 200


@bp.post("/cases/<int:case_id>/comments")
@security.require_auth
def create_comment(case_id: int):
    data = body_of(request)
    body = clean(data.get("body"), comments_service.BODY_MAX_LENGTH)
    parent_comment_id = data.get("parent_comment_id")

    if not body:
        return fail("invalid", "לא ניתן לשלוח תגובה ריקה.")

    if parent_comment_id is not None:
        try:
            parent_comment_id = int(parent_comment_id)
        except (TypeError, ValueError):
            return fail("invalid", "התגובה שאליה ניסית להשיב אינה תקינה.")

    # This endpoint only ever creates role='user'. Testimony has its own
    # endpoint with its own permission rules, and the trial roles are written
    # by the worker alone.
    result, comment_id = comments_service.create_comment(
        case_id, g.user_id, body, role="user", parent_comment_id=parent_comment_id
    )

    if result == "not_found":
        return fail("not_found", "התיק המבוקש לא נמצא.")
    if result == "invalid":
        return fail("invalid", "התגובה אינה תקינה.")
    if result == "rejected":
        return fail("rejected", "התגובה נחסמה על ידי מנגנון סינון התוכן.")

    return jsonify(
        {"comment": comments_service.get_shaped(comment_id, viewer_id=g.user_id)}
    ), 201

server/app/api/trial.py:
"""Trial actions and the trial read model.

Separate from cases.py because these endpoints have a completely different
permission model: gated by phase, and by whether you are a party to the case.
"""

from __future__ import annotations

from flask import Blueprint, g, jsonify, request

from .. import security
from ..errors import fail
from ..services import (
    agents_service,
    cases_service,
    comments_service,
    jury_service,
    summons_service,
)
from ..validation import body_of, clean

bp = Blueprint("trial", __name__)


def _shape_member(row) -> dict:
    return {
        "seat": int(row["seat"]),
        "juror": {
            "id": row["juror_user_id"],
            "name": row["juror_name"],
            "avatar_url": row["avatar_url"],
            "is_bot": True,
            "personality_name": row.get("personality_name"),
        },
        # Absolute, so the UI can show when a juror is expected to speak.
        "speaks_at": row["speaks_at"].isoformat(timespec="seconds") if row["speaks_at"] else None,
        "spoke_at": row["spoke_at"].isoformat(timespec="seconds") if row["spoke_at"] else None,
        # Null until they speak - the panel shows who is still to be heard.
        "vote": row["vote"],
        "comment_id": row["comment_id"],
    }


@bp.get("/cases/<int:case_id>/trial")
@security.optional_auth
def get_trial(case_id: int):
    """Everything about the trial itself: the panel, the votes, the witnesses.

    Also reports what the VIEWER may do right now, so the client never has to
    reimplement the phase and party rules to decide which buttons to show.
    """
    case = cases_service.get_raw(case_id)
    if case is None:
        return fail("not_found", "התיק המבוקש לא נמצא.")

    panel = jury_service.get_panel(case_id)
    members = jury_service.get_members(case_id)
    summonses = summons_service.list_for_case(case_id)

    viewer_side = summons_service.side_for(case, g.user_id) if g.user_id else None
    counts = summons_service.counts_by_side(case_id)
    my_summons = next(
        (s for s in summonses if g.user_id and s["witness"]["id"] == g.user_id), None
    )

    return jsonify(
        {
            "panel": (
                {
                    "judge": {
                        "id": panel["judge_user_id"],
                        "name": panel["judge_name"],
                        "personality_name": panel["judge_personality"],
                        "is_bot": True,
                    },
                    "tally_guilty": panel["tally_guilty"],
                    "tally_not_guilty": panel["tally_not_guilty"],
                    "tiebreak_used": bool(panel["tiebreak_used"]),
                    "members": [_shape_member(row) for row in members],
                }
                if panel
                else None
            ),
            "summons": summonses,
            "viewer": {
                "side": viewer_side,
                # A party may summon while the phase is open and their side has
                # room; the client just reads this.
                "can_summon": bool(
                    viewer_side
                    and case["status"] == "witness_phase"
                    and counts[viewer_side] < summons_service.MAX_WITNESSES_PER_SIDE
                ),
                "summons_remaining": (
                    summons_service.MAX_WITNESSES_PER_SIDE - counts[viewer_side]
                    if viewer_side
                    else 0
                ),
                "can_testify": bool(
                    my_summons
                    and my_summons["status"] == "pending"
                    and case["status"] == "witness_phase"
                ),
            },
        }
    ), 200


@bp.post("/cases/<int:case_id>/summons")
@security.require_auth
def summon_witness(case_id: int):
    data = body_of(request)
    try:
        witness_id = int(data.get("witness_user_id"))
    except (TypeError, ValueError):
        return fail("invalid", "יש לבחור עד.")

    result, _summons_id = summons_service.summon(case_id, g.user_id, witness_id)

    messages = {
        "not_found": "התיק או המשתמש המבוקש לא נמצאו.",
        "closed": "שלב איסוף העדויות הסתיים.",
        "forbidden": "רק צד לתיק רשאי לזמן עדים.",
        "invalid": "אפשר לזמן רק משתמשים אנושיים שאינם צד לתיק.",
        "conflict": "העד כבר זומן, או שניצלת את מכסת שלושת העדים.",
    }
    if result != "ok":
        return fail(result, messages.get(result))

    return jsonify({"summons": summons_service.list_for_case(case_id)}), 201


@bp.post("/cases/<int:case_id>/testify")
@security.require_auth
def testify(case_id: int):
    data = body_of(request)
    body = clean(data.get("body"), comments_service.BODY_MAX_LENGTH)
    if not body:
        return fail("invalid", "לא ניתן למסור עדות ריקה.")

    result, comment_id = summons_service.testify(case_id, g.user_id, body)

    messages = {
        "not_found": "התיק המבוקש לא נמצא.",
        "closed": "שלב איסוף העדויות הסתיים.",
        "forbidden": "רק עד שזומן לתיק רשאי למסור עדות.",
        "conflict": "כבר מסרת עדות בתיק הזה.",
        "invalid": "העדות אינה תקינה.",
    }
    if result != "ok":
        return fail(result, messages.get(result))

    return jsonify({"comment_id": comment_id}), 201


@bp.get("/me/summons")
@security.require_auth
def my_summons():
    """Cases waiting on me to testify."""
    return jsonify({"summons": summons_service.pending_for_user(g.user_id)}), 200


@bp.get("/agents")
def list_agents():
    """The court's permanent staff - what the /about page is built from.

    Never returns `personality_prompt`: that is the instruction the brain is
    given, not something the public needs, and publishing it would hand anyone
    the exact text to imitate a juror.
    """
    roster = []
    for role in ("judge", "juror", "moderator"):
        for user_id in agents_service.pool_ids(role):
            agent = agents_service.get_agent(user_id)
            roster.append(
                {
                    "id": agent["user_id"],
                    "name": agent["name"],
                    "bio": agent["bio"],
                    "avatar_url": agent["avatar_url"],
                    "role": agent["role"],
                    "moderator_kind": agent["moderator_kind"],
                    "personality_name": agent["personality_name"],
                    "tone_tag": agent["tone_tag"],
                }
            )
    return jsonify({"agents": roster}), 200

server/app/db.py:
"""Database access: connections and a very thin query helper.

Two rules hold everywhere below the service layer:

1. **Placeholders are MySQL's own `%s`.** There is no `?` translation layer.
   The previous generation of this project had one, and it was exactly what
   made running the test suite against SQLite look reasonable - which in turn
   meant the tests never exercised the dialect the application actually speaks.

2. **`Db` is a convenience, not an abstraction.** It hands parameters straight
   to PyMySQL and returns plain dicts. It exists only so that services can say
   what they mean in one line instead of five lines of cursor bookkeeping.
"""

from __future__ import annotations

import logging
import time
from dataclasses import dataclass
from typing import Any, Iterable, Sequence

import pymysql
from pymysql.cursors import DictCursor

from .config import get_settings

log = logging.getLogger(__name__)

Params = Sequence[Any] | dict[str, Any]


@dataclass(frozen=True)
class ExecResult:
    """What a write statement did.

    `rowcount` is load-bearing throughout the trial engine: every state
    transition is a conditional UPDATE guarded on the status it expects to
    find, and a rowcount of 0 means another worker got there first.
    """

    rowcount: int
    lastrowid: int


class Db:
    """A PyMySQL connection with the cursor boilerplate folded away."""

    def __init__(self, raw: pymysql.connections.Connection) -> None:
        self._raw = raw

    # --- reads --------------------------------------------------------------

    def query_all(self, sql: str, params: Params = ()) -> list[dict[str, Any]]:
        with self._raw.cursor() as cur:
            cur.execute(sql, params)
            return list(cur.fetchall())

    def query_one(self, sql: str, params: Params = ()) -> dict[str, Any] | None:
        with self._raw.cursor() as cur:
            cur.execute(sql, params)
            return cur.fetchone()

    def query_value(self, sql: str, params: Params = (), default: Any = None) -> Any:
        """First column of the first row - for COUNT(*), EXISTS, one id, etc."""
        row = self.query_one(sql, params)
        if not row:
            return default
        return next(iter(row.values()))

    # --- writes -------------------------------------------------------------

    def execute(self, sql: str, params: Params = ()) -> ExecResult:
        with self._raw.cursor() as cur:
            cur.execute(sql, params)
            return ExecResult(rowcount=cur.rowcount, lastrowid=cur.lastrowid)

    def execute_many(self, sql: str, seq: Iterable[Params]) -> ExecResult:
        rows = list(seq)
        if not rows:
            return ExecResult(rowcount=0, lastrowid=0)
        with self._raw.cursor() as cur:
            cur.executemany(sql, rows)
            return ExecResult(rowcount=cur.rowcount, lastrowid=cur.lastrowid)

    # --- transaction control ------------------------------------------------

    def commit(self) -> None:
        self._raw.commit()

    def rollback(self) -> None:
        self._raw.rollback()

    def close(self) -> None:
        try:
            self._raw.close()
        except Exception:  # pragma: no cover - closing a dead socket
            pass


def connect(**overrides: Any) -> Db:
    """Open one connection. Callers are responsible for closing it.

    autocommit is deliberately off: the trial engine's correctness depends on
    grouping "claim the row" and "record the result" into one transaction.
    """
    s = get_settings()
    kwargs: dict[str, Any] = {
        "host": s.db_host,
        "port": s.db_port,
        "user": s.db_user,
        "password": s.db_password,
        "database": s.db_name,
        "charset": "utf8mb4",
        "cursorclass": DictCursor,
        "autocommit": False,
    }
    kwargs.update(overrides)
    return Db(pymysql.connect(**kwargs))


def get_db(**overrides: Any) -> Db:
    """connect(), but tolerant of a MySQL container that is still booting."""
    attempts = int(overrides.pop("attempts", 1))
    delay = float(overrides.pop("delay", 2.0))
    last: Exception | None = None
    for attempt in range(attempts):
        try:
            return connect(**overrides)
        except pymysql.err.OperationalError as exc:  # pragma: no cover - boot race
            last = exc
            if attempt < attempts - 1:
                log.warning("database not ready (%s), retrying in %.1fs", exc, delay)
                time.sleep(delay)
    raise last  # type: ignore[misc]  # pragma: no cover


def wait_for_db(attempts: int = 30, delay: float = 2.0) -> Db:  # pragma: no cover
    """Used by the long-lived processes (worker, seed) at start-up."""
    return get_db(attempts=attempts, delay=delay)


class _OwnedConnection:
    """Context manager implementing the `conn=None` convention.

    Every service function takes an optional `conn`. When one is supplied the
    caller owns the transaction - the service must not commit or close it, so
    a route or a worker task can compose several service calls atomically.
    When none is supplied the service opens its own, commits on success and
    always closes.

        with owned(conn) as db:
            db.execute(...)
            db.commit_if_owned()
    """

    def __init__(self, conn: Db | None) -> None:
        self._owned = conn is None
        self.db = conn if conn is not None else connect()

    def __enter__(self) -> "_OwnedConnection":
        return self

    def __exit__(self, exc_type, exc, tb) -> bool:
        if self._owned:
            if exc_type is not None:
                self.db.rollback()
            self.db.close()
        return False

    @property
    def owned(self) -> bool:
        return self._owned

    def commit_if_owned(self) -> None:
        if self._owned:
            self.db.commit()

    # Delegate the query surface so callers can use the wrapper directly.
    def query_all(self, sql: str, params: Params = ()) -> list[dict[str, Any]]:
        return self.db.query_all(sql, params)

    def query_one(self, sql: str, params: Params = ()) -> dict[str, Any] | None:
        return self.db.query_one(sql, params)

    def query_value(self, sql: str, params: Params = (), default: Any = None) -> Any:
        return self.db.query_value(sql, params, default)

    def execute(self, sql: str, params: Params = ()) -> ExecResult:
        return self.db.execute(sql, params)

    def execute_many(self, sql: str, seq: Iterable[Params]) -> ExecResult:
        return self.db.execute_many(sql, seq)


def owned(conn: Db | None) -> _OwnedConnection:
    return _OwnedConnection(conn)
